  insert into public.t3a_d1_branch_rule(dimension_id, rule_code, rule_condition, rule_effect, rule_order) values ('D5','BR-D5-05','Q-D5-05 returns A1','Q-D5-05b served. Which options exists only once a change to an available option was stated',5);
  insert into public.t3a_d1_branch_rule(dimension_id, rule_code, rule_condition, rule_effect, rule_order) values ('D5','BR-D5-06','Q-D5-06 returns A1','Q-D5-06b served. Which routes exists only once a listed route was used',6);
  insert into public.t3a_d1_branch_rule(dimension_id, rule_code, rule_condition, rule_effect, rule_order) values ('D5','BR-D5-07','Q-D5-07 returns A1, A2','Q-D5-07b served. Which contents exists only once an agreement was stated',7);
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D5-EXEC-001-CONSTRUCT', 'construct'::public.t3a_content_family, 'D5 construct', 'D5', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"situation_classes": {"SC-D5-1": {"situation": "Two parties hold different positions on a decision both must work under", "pattern_family": "IPF-D5-01"}, "SC-D5-2": {"situation": "A contribution the source establishes as the participant''s has been presented as another party''s", "pattern_family": "IPF-D5-02"}, "SC-D5-3": {"situation": "A resource, window or capacity is claimed by two parties and cannot serve both", "pattern_family": "IPF-D5-03"}, "SC-D5-4": {"situation": "Work divided between parties is not arriving from one side", "pattern_family": "IPF-D5-04"}, "SC-D5-5": {"situation": "The participant must obtain something from a party over whom the source establishes they have no authority", "pattern_family": "IPF-D5-05"}, "SC-D5-6": {"situation": "A working relationship must be formed where the source establishes none exists", "pattern_family": "IPF-D5-06"}, "SC-D5-7": {"situation": "A difference between two other parties is affecting work the participant holds", "pattern_family": "IPF-D5-07"}}, "conduct_elements": {"CE-D5-01": {"name": "Position stated", "supports": "A stated position is the participant''s own act and needs no reading of the other party", "does_not_support": "Does not support a claim that the position was reasonable, firm or flexible"}, "CE-D5-02": {"name": "Information sought", "supports": "The source designates what could be asked before observation, so the selection is bounded", "does_not_support": "Does not support a claim about curiosity, openness or good faith"}, "CE-D5-03": {"name": "Common ground named", "supports": "The shared items are established by the source, not judged by the mentor", "does_not_support": "Does not support a claim that common ground existed in fact, or that naming it helped"}, "CE-D5-04": {"name": "Proposal made", "supports": "Options are pre-listed, so a proposal is observable rather than evaluated", "does_not_support": "Does not support a claim that the proposal was fair, workable or well judged"}, "CE-D5-05": {"name": "Adjustment offered", "supports": "A change to one''s own position is an act of the participant alone", "does_not_support": "Does not support a claim about willingness, generosity or weakness, and NEVER supports a comparison with what the other party offered"}, "CE-D5-06": {"name": "Route used", "supports": "Routes are pre-listed with their in-session performability", "does_not_support": "Does not support a claim that the route chosen was correct, or that using an authority was avoidance"}, "CE-D5-07": {"name": "What was agreed and recorded", "supports": "Whether something was stated as agreed and whether recording was stated are both facts", "does_not_support": "DOES NOT SUPPORT A CLAIM THAT THE MATTER WAS RESOLVED. An agreement stated is an act; an outcome is not observed"}, "CE-D5-08": {"name": "Continuation stated", "supports": "The source establishes that the difference may persist, so the statement is bounded", "does_not_support": "Does not support a prediction, or a judgment that the continuation was adequate"}, "CE-D5-09": {"name": "Conduct when the exchange was put back", "supports": "The test point is authored into the source, so the opportunity is identical for every participant", "does_not_support": "Does not support a claim about consistency, defensiveness or self-awareness"}}, "coverage": {"CE-D5-01": ["Carried", "Carried", "Carried", "Carried"], "CE-D5-02": ["Carried", "Carried", "Carried", "Carried"], "CE-D5-03": ["Carried", "Carried", "Carried", "Carried"], "CE-D5-04": ["Carried", "Carried", "Carried", "Carried"], "CE-D5-05": ["Carried", "Carried", "Carried", "Carried"], "CE-D5-06": ["NOT SERVED", "Carried", "NOT SERVED", "Carried"], "CE-D5-07": ["Carried", "Carried", "Carried", "Carried"], "CE-D5-08": ["Carried", "Carried", "Carried", "Carried"], "CE-D5-09": ["Carried", "Carried", "NOT IN LAUNCH DESIGN", "Carried"]}, "source_fields": {"permitted_administration_variance": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The administration variance the source permits, recorded wherever it occurs"}, "unsupported_inferences": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The inferences the source must never support"}, "compatibility_class": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The delivery form class of the source, derived from its Stage"}, "designated_positions": {"type": "list: DP", "stages": "1, 2, 3, 4", "holds": "The positions the source establishes as available to the participant as their own; consumed by Q-D5-01b"}, "designated_enquiries": {"type": "list: DE", "stages": "1, 2, 3, 4", "holds": "The questions the participant could put about the other position; each is a question the participant asks, never an answer the counterpart gives; consumed by Q-D5-02b"}, "shared_items": {"type": "list: SI, mapped", "stages": "1, 2, 3, 4", "holds": "The facts or interests the source establishes as common to both parties, each quoted in the material map; never the counterpart''s position; consumed by Q-D5-03b"}, "available_options": {"type": "list: AO", "stages": "1, 2, 3, 4", "holds": "The options the source makes available for proposal or for a change to the participant''s own position; consumed by Q-D5-04b and Q-D5-05b, each as its own determination"}, "available_routes": {"type": "list: AR", "stages": "1, 2, 3, 4", "holds": "The routes whose use can complete and be evidenced at the Stage; consumed by Q-D5-06b. A route that can only be stated as an intention is never listed"}, "agreement_contents": {"type": "list: AC", "stages": "1, 2, 3, 4", "holds": "The contents an agreement could hold; consumed by Q-D5-07b"}, "counterpart_role": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The role label of the other party. Retained for source truth; never rendered, never on the mentor reference card, never the subject of any entry"}, "counterpart_position": {"type": "text", "stages": "1, 2, 3, 4", "holds": "What the source establishes as the other party''s position. Retained for source truth; never rendered, never on the mentor reference card, never the subject of any entry"}, "difference_established": {"type": "text", "stages": "1, 2, 3, 4", "holds": "Where the participant meets the difference, competing claim or absent relationship the source establishes"}, "authority_relation": {"type": "text", "stages": "1, 2, 3, 4", "holds": "What the source establishes about authority between the parties, or None"}, "recording_route": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The route by which an agreement would be recorded, or None"}, "persistence_point": {"type": "text", "stages": "1, 2, 3, 4", "holds": "What the source establishes happens if the difference continues, or None"}, "exchange_test_point": {"type": "point: Account test", "stages": "1, 2, 4", "holds": "The reveal or beat at which the participant''s own part in the exchange is put back to them, or None"}, "list_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "Why a list is empty, and any item withheld from a list as not selectable, or None"}, "source_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "A shared Stage 3 submission, a higher review standard or other situation context the source carries, or None"}, "situation_class_label": {"type": "text", "stages": "1, 2, 3, 4", "holds": "One approved generic phrase naming the kind of situation; never the source title or scenario detail"}, "observation_mode_label": {"type": "enum: written_response, structured_live_session, work_sample, group_session", "stages": "1, 2, 3, 4", "holds": "The observation mode of the Stage at which the source is served"}}, "source": "T3A-D5-EXEC-001 v2.0"}'::jsonb from public.t3a_content_object where identifier = 'T3A-D5-EXEC-001-CONSTRUCT' and family = 'construct'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D5-EXEC-001-DETERMINATION', 'determination_question_set'::public.t3a_content_family, 'D5 determination set', 'D5', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"questions": {"Q-D5-01": {"element": "CE-D5-01", "capture_set": "C1", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D5-01b": {"element": "CE-D5-01", "capture_set": "C1b", "answer_type": "Bound selection, one or more", "source_bound_to": "designated_positions", "served_when": "C1 records a designated position stated"}, "Q-D5-02": {"element": "CE-D5-02", "capture_set": "C2", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D5-02b": {"element": "CE-D5-02", "capture_set": "C2b", "answer_type": "Bound selection, one or more", "source_bound_to": "designated_enquiries", "served_when": "C2 records a designated question asked"}, "Q-D5-03": {"element": "CE-D5-03", "capture_set": "C3", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D5-03b": {"element": "CE-D5-03", "capture_set": "C3b", "answer_type": "Bound selection, one or more", "source_bound_to": "shared_items", "served_when": "C3 records a designated shared item named"}, "Q-D5-04": {"element": "CE-D5-04", "capture_set": "C4", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D5-04b": {"element": "CE-D5-04", "capture_set": "C4b", "answer_type": "Bound selection, one or more", "source_bound_to": "available_options", "served_when": "C4 records an available option proposed"}, "Q-D5-05": {"element": "CE-D5-05", "capture_set": "C5", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D5-05b": {"element": "CE-D5-05", "capture_set": "C5b", "answer_type": "Bound selection, one or more", "source_bound_to": "available_options", "served_when": "C5 records a change to an available option"}, "Q-D5-06": {"element": "CE-D5-06", "capture_set": "C6", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries a selectable available_routes item, at Stages 2 and 4"}, "Q-D5-06b": {"element": "CE-D5-06", "capture_set": "C6b", "answer_type": "Bound selection, one or more", "source_bound_to": "available_routes", "served_when": "C6 records a listed route used"}, "Q-D5-07": {"element": "CE-D5-07", "capture_set": "C7", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D5-07b": {"element": "CE-D5-07", "capture_set": "C7b", "answer_type": "Bound selection, one or more", "source_bound_to": "agreement_contents", "served_when": "C7 records an agreement stated"}, "Q-D5-08": {"element": "CE-D5-08", "capture_set": "C8", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D5-09": {"element": "CE-D5-09", "capture_set": "C9", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries exchange_test_point"}}, "capture_sets": {"C1": {"title": "What the participant stated as their own position", "lines": ["Stated as their own a position the source designates.", "Stated as their own a position the source does not designate.", "Stated no position of their own during the observation."], "bound": null, "type": "content", "whole_session": "Stated no position of their own during the observation."}, "C1b": {"title": "Which designated positions were stated", "lines": ["LISTED Selected each designated position stated as the participant''s own.", "LISTED + STATED_UNLISTED_POSITION Selected the designated positions stated and a position outside the list."], "bound": {"field": "designated_positions", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C2": {"title": "Whether the participant asked about the other position", "lines": ["Asked about the other position using one or more of the questions the source designates.", "Asked about the other position using a question the source does not designate.", "Asked nothing about the other position during the observation."], "bound": null, "type": "content", "whole_session": "Asked nothing about the other position during the observation."}, "C2b": {"title": "Which designated questions were asked", "lines": ["LISTED Selected each designated question asked.", "LISTED + ASKED_UNLISTED_QUESTION Selected the designated questions asked and a question outside the list."], "bound": {"field": "designated_enquiries", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C3": {"title": "Which shared items the participant named", "lines": ["Named one or more of the shared items the source designates.", "Named a shared item the source does not designate.", "Named no shared item during the observation."], "bound": null, "type": "content", "whole_session": "Named no shared item during the observation."}, "C3b": {"title": "Which designated shared items were named", "lines": ["LISTED Selected each designated shared item named.", "LISTED + NAMED_UNLISTED_ITEM Selected the designated shared items named and an item outside the list."], "bound": {"field": "shared_items", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C4": {"title": "What the participant proposed", "lines": ["Proposed one or more of the options the source makes available.", "Proposed an option the source does not make available.", "Proposed nothing during the observation."], "bound": null, "type": "content", "whole_session": "Proposed nothing during the observation."}, "C4b": {"title": "Which available options were proposed", "lines": ["LISTED Selected each available option proposed.", "LISTED + PROPOSED_UNLISTED_OPTION Selected the available options proposed and an option outside the list."], "bound": {"field": "available_options", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C5": {"title": "What the participant stated they would change in their own position", "lines": ["Stated a change to their own position to an option the source makes available.", "Stated a change to their own position outside the options the source makes available.", "Stated that their own position would not change.", "Stated nothing about changing their own position during the observation."], "bound": null, "type": "content", "whole_session": "Stated nothing about changing their own position during the observation."}, "C5b": {"title": "Which available options the stated change moved to", "lines": ["LISTED Selected each available option the stated change moved to.", "LISTED + CHANGED_TO_UNLISTED_OPTION Selected the available options the stated change moved to and an option outside the list."], "bound": {"field": "available_options", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C6": {"title": "Which route the participant used", "lines": ["Used a route the source makes available.", "Used a route the source does not make available.", "Used no route during the observation."], "bound": null, "type": "content", "whole_session": "Used no route during the observation."}, "C6b": {"title": "Which listed routes were used", "lines": ["LISTED Selected each listed route used.", "LISTED + USED_UNLISTED_ROUTE Selected the listed routes used and a route outside the list."], "bound": {"field": "available_routes", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C7": {"title": "Whether an agreement was stated, and whether recording was stated", "lines": ["Stated an agreement and stated that it would be recorded.", "Stated an agreement with no statement about recording it.", "Stated no agreement during the observation.", "Stated that no agreement had been reached."], "bound": null, "type": "content", "whole_session": "Stated no agreement during the observation."}, "C7b": {"title": "Which designated contents the stated agreement held", "lines": ["LISTED Selected each designated content the stated agreement held.", "AGREED_UNLISTED_CONTENT The stated agreement held a content outside the list and none of the listed contents.", "LISTED + AGREED_UNLISTED_CONTENT Selected the designated contents the stated agreement held and a content outside the list."], "bound": {"field": "agreement_contents", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C8": {"title": "What the participant stated would happen if the difference continues", "lines": ["Stated a next step and stated who it would go to.", "Stated a next step without stating who it would go to.", "Stated that the difference would be taken to an authority.", "Stated nothing about the difference continuing during the observation."], "bound": null, "type": "content", "whole_session": "Stated nothing about the difference continuing during the observation."}, "C9": {"title": "What was stated when the participant''s own part in the exchange was put back", "lines": ["Stated the same content as their own earlier part in the exchange.", "Stated content that differs from their own earlier part in the exchange.", "Stated that what was put back was not what they had said.", "Stated nothing about what was put back during the observation."], "bound": null, "type": "content", "whole_session": "Stated nothing about what was put back during the observation."}}, "branch_rules": {"BR-D5-01": {"child": "Q-D5-01b", "parent": "Q-D5-01", "serving_answers": ["A1"], "note": "Which positions exists only once a designated position was stated"}, "BR-D5-02": {"child": "Q-D5-02b", "parent": "Q-D5-02", "serving_answers": ["A1"], "note": "Which questions exists only once a designated question was asked"}, "BR-D5-03": {"child": "Q-D5-03b", "parent": "Q-D5-03", "serving_answers": ["A1"], "note": "Which shared items exists only once a designated shared item was named"}, "BR-D5-04": {"child": "Q-D5-04b", "parent": "Q-D5-04", "serving_answers": ["A1"], "note": "Which options exists only once an available option was proposed"}, "BR-D5-05": {"child": "Q-D5-05b", "parent": "Q-D5-05", "serving_answers": ["A1"], "note": "Which options exists only once a change to an available option was stated"}, "BR-D5-06": {"child": "Q-D5-06b", "parent": "Q-D5-06", "serving_answers": ["A1"], "note": "Which routes exists only once a listed route was used"}, "BR-D5-07": {"child": "Q-D5-07b", "parent": "Q-D5-07", "serving_answers": ["A1", "A2"], "note": "Which contents exists only once an agreement was stated"}}, "source": "T3A-D5-EXEC-001 v2.0"}'::jsonb from public.t3a_content_object where identifier = 'T3A-D5-EXEC-001-DETERMINATION' and family = 'determination_question_set'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D5-EXEC-001-STATEMENT-LIBRARY', 'statement_library'::public.t3a_content_family, 'D5 statement library', 'D5', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"comparison_operators": {}, "placeholder_grammar": {"stated_position_count": {"kind": "count", "bound_to": "Q-D5-01b LISTED", "grammar": "whole number from 1 to the number of items in designated_positions"}, "asked_question_count": {"kind": "count", "bound_to": "Q-D5-02b LISTED", "grammar": "whole number from 1 to the number of items in designated_enquiries"}, "named_item_count": {"kind": "count", "bound_to": "Q-D5-03b LISTED", "grammar": "whole number from 1 to the number of items in shared_items"}, "proposed_option_count": {"kind": "count", "bound_to": "Q-D5-04b LISTED", "grammar": "whole number from 1 to the number of items in available_options"}, "changed_option_count": {"kind": "count", "bound_to": "Q-D5-05b LISTED", "grammar": "whole number from 1 to the number of items in available_options"}, "used_route_count": {"kind": "count", "bound_to": "Q-D5-06b LISTED", "grammar": "whole number from 1 to the number of items in available_routes"}, "agreement_content_count": {"kind": "count", "bound_to": "Q-D5-07b LISTED", "grammar": "whole number from 1 to the number of items in agreement_contents"}}, "recurrence_keys": {"REK-D5-001": {"element": "CE-D5-01", "proposition": "A position of their own was or was not stated", "material_variable": "Whether a position was stated", "contextual_variable": "Which position; the subject"}, "REK-D5-002": {"element": "CE-D5-02", "proposition": "The other position was or was not asked about", "material_variable": "Whether an enquiry was made", "contextual_variable": "Which questions"}, "REK-D5-003": {"element": "CE-D5-03", "proposition": "A shared item was or was not named", "material_variable": "Whether shared ground was named", "contextual_variable": "Which items"}, "REK-D5-004": {"element": "CE-D5-04", "proposition": "A proposal was or was not made", "material_variable": "Whether a proposal was made", "contextual_variable": "Which option"}, "REK-D5-005": {"element": "CE-D5-05", "proposition": "A change to their own position was or was not stated", "material_variable": "Whether a change was offered", "contextual_variable": "Which change; how far"}, "REK-D5-006": {"element": "CE-D5-06", "proposition": "An available route was or was not used", "material_variable": "Whether a listed route was used", "contextual_variable": "Which route"}, "REK-D5-007": {"element": "CE-D5-07", "proposition": "An agreement was or was not stated, and recording was or was not stated", "material_variable": "Whether both were stated", "contextual_variable": "What the agreement held"}, "REK-D5-008": {"element": "CE-D5-08", "proposition": "A next step for a persisting difference was or was not stated", "material_variable": "Whether a step was stated", "contextual_variable": "Which step; to whom"}, "REK-D5-009": {"element": "CE-D5-09", "proposition": "The restated part did or did not match the record", "material_variable": "Whether it matched", "contextual_variable": "How far it differed"}}, "resolution_rules": {"RR-D5-01": {"pattern": "Q-D5-01=A1 + Q-D5-01b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent records a designated position stated and the child identifies none"}, "RR-D5-02": {"pattern": "Q-D5-02=A1 + Q-D5-02b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent records a designated question asked and the child identifies none"}, "RR-D5-03": {"pattern": "Q-D5-03=A1 + Q-D5-03b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent records a designated shared item named and the child identifies none"}, "RR-D5-04": {"pattern": "Q-D5-04=A1 + Q-D5-04b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent records an available option proposed and the child identifies none"}, "RR-D5-05": {"pattern": "Q-D5-05=A1 + Q-D5-05b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent records a change to an available option and the child identifies none"}, "RR-D5-06": {"pattern": "Q-D5-06=A1 + Q-D5-06b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent records a listed route used and the child identifies none"}, "RR-D5-07": {"pattern": "Q-D5-07=A1 + Q-D5-07b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent records an agreement stated and the child identifies none of its contents"}, "RR-D5-08": {"pattern": "Q-D5-07=A2 + Q-D5-07b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent records an agreement stated and the child identifies none of its contents"}, "RR-D5-09": {"pattern": "Q-D5-07=A1 + Q-D5-04=A3 + Q-D5-05=A4", "outcome": "REFUSE", "reason": "An agreement is recorded as stated where nothing was proposed and no change was stated; one of the three determinations is wrong and the service must not choose"}, "RR-D5-10": {"pattern": "Q-D5-07=A2 + Q-D5-04=A3 + Q-D5-05=A4", "outcome": "REFUSE", "reason": "An agreement is recorded as stated where nothing was proposed and no change was stated; one of the three determinations is wrong and the service must not choose"}}, "templates": {"L-D5-ONE-001": "In one situation, recorded in {context_label} on {observation_date}: {observation_statement}", "L-D5-MC-001": "In {context_count} recorded contexts identified in this report, the following conduct was recorded.", "L-D5-REC-001": "The same recorded conduct was observed in {context_labels}. Each observation renders against its own context.", "L-D5-DIV-001": "The observations that follow differ. Each is recorded against its own context and neither is presented in preference to the other.", "L-D5-ATT-001": "An earlier observation in this dimension recorded different conduct. Both remain in the record.", "L-D5-COMP-001": "The conditions of this observation were affected by a recorded technical event.", "L-D5-EXP-001": "This observation falls outside the current evidence period.", "L-D5-AMEND-001": "This entry supersedes an earlier entry following a completed correc