  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S1-001', 'source'::public.t3a_content_family, 'THE TOOL THE TEAM WILL NOT TAKE UP', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE TOOL THE TEAM WILL NOT TAKE UP", "source_digest": "0e32e1aeda7eb1c85357e9af00a45bfb14f1120f2b648f9172ed641b1c108ec6", "situation": "You coordinate process improvement for a team of six that handles client intake. For the past year the team has tracked onboarding documents on a manual spreadsheet. You have identified a project management tool that would automate about sixty per cent of the tracking, and you have costed it and tested it.\n\nYou raised it at the team meeting. The response across the team was that the spreadsheet works, that a new system means learning it during the busiest quarter, and that a previous tool was introduced two years ago and abandoned.\n\nWhat the record shows: the abandoned tool was a different product, withdrawn by its vendor; the busiest quarter runs eight weeks from now; a phased option exists in which one intake stream moves first; and your manager has said the decision is the team''s to make together.", "reveals": [{"code": "R1", "text": "What do you state as your own position?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you ask the team?", "role": "Information"}, {"code": "R3", "text": "What do you put forward?", "role": "Information"}, {"code": "R4", "text": "Is there anything in your own position you would change, and to what?", "role": "Information"}, {"code": "R5", "text": "If the team does not take it up, what happens next?", "role": "Information"}, {"code": "R6", "text": "Your manager writes, \"You told the team you would drop it if they said no. Did you?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three designated positions; R1 asks directly"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three designated enquiries; R2 creates the opportunity"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three shared items"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Four available options — the widest option set in the bank"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "R4 asks what would change in the participant''s own position"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Same family as Q-D5-04b, captured independently"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A written response cannot evidence a route used"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "The source designates no available_routes item, so the bound question cannot be offered"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents and a recording route"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "R5 asks what happens if it is not taken up"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "the tracking work itself falls on the whole team", "Where the participant meets it": "The situation", "Quoted text": "the team has tracked onboarding documents"}, {"Item": "SI2", "Item text": "the busy quarter is eight weeks away for everyone", "Where the participant meets it": "The situation", "Quoted text": "the busiest quarter runs eight weeks from now"}, {"Item": "SI3", "Item text": "the previous tool''s withdrawal was the vendor''s, not the team''s", "Where the participant meets it": "The situation", "Quoted text": "a different product, withdrawn by its vendor"}], "source_sheet": {"d5_situation_class": "SC-D5-1", "workplace_demand": "Putting forward a costed change to a shared way of working that the team has said it does not want before its busiest quarter.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The team''s conduct, reasoning or fairness, which is never recorded or rendered; the tool''s merits.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the team was resistant or the participant persistent; that adoption is the right outcome; anything about persuasion.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "designated_positions": [{"id": "DP1", "text": "adopt the tool across all streams"}, {"id": "DP2", "text": "adopt it for one intake stream first"}, {"id": "DP3", "text": "keep the spreadsheet through the busy quarter and revisit after"}], "designated_enquiries": [{"id": "DE1", "text": "what the team found unworkable in the abandoned tool"}, {"id": "DE2", "text": "what the spreadsheet does that the tool would have to match"}, {"id": "DE3", "text": "what timing would not fall in the busy quarter"}], "shared_items": [{"id": "SI1", "text": "the tracking work itself falls on the whole team"}, {"id": "SI2", "text": "the busy quarter is eight weeks away for everyone"}, {"id": "SI3", "text": "the previous tool''s withdrawal was the vendor''s, not the team''s"}], "available_options": [{"id": "AO1", "text": "phase one stream first"}, {"id": "AO2", "text": "defer to after the busy quarter"}, {"id": "AO3", "text": "run both systems in parallel for one cycle"}, {"id": "AO4", "text": "drop the proposal"}], "available_routes": [], "agreement_contents": [{"id": "AC1", "text": "which option"}, {"id": "AC2", "text": "when it would start"}, {"id": "AC3", "text": "who would run it"}], "counterpart_role": "The team of six.", "counterpart_position": "The spreadsheet works and a change in the busy quarter is unwelcome.", "difference_established": "The team''s response at the meeting, at the situation.", "authority_relation": "\"the decision is the team''s to make together.\" Exact text.", "recording_route": "The team meeting note.", "persistence_point": "The busy quarter begins in eight weeks and the spreadsheet continues.", "exchange_test_point": "R6", "list_note": "Not selectable in available_routes, because a written response cannot evidence a route used: the team meeting; individually before the next meeting; through the manager.", "source_note": null, "situation_class_label": "Two parties holding different positions on a decision both must work under", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D5-S1-001", "stage_code": "S1", "source_version_hash": "0e32e1aeda7eb1c85357e9af00a45bfb14f1120f2b648f9172ed641b1c108ec6", "serving_eligible": false, "verbatim": "You coordinate process improvement for a team of six that handles client intake. For the past year the team has tracked onboarding documents on a manual spreadsheet. You have identified a project management tool that would automate about sixty per cent of the tracking, and you have costed it and tested it.\n\nYou raised it at the team meeting. The response across the team was that the spreadsheet works, that a new system means learning it during the busiest quarter, and that a previous tool was introduced two years ago and abandoned.\n\nWhat the record shows: the abandoned tool was a different product, withdrawn by its vendor; the busiest quarter runs eight weeks from now; a phased option exists in which one intake stream moves first; and your manager has said the decision is the team''s to make together."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S1-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S1-002', 'source'::public.t3a_content_family, 'THE FIRST DAY WITH NOTHING ASSIGNED', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE FIRST DAY WITH NOTHING ASSIGNED", "source_digest": "5d0b6db49c19b105a1af96075dc4ad77ab10306ed2f2435adf588f9169e10713", "situation": "It is your first day as a project analyst at a consulting firm. Your manager introduced you to the team this morning and left for client meetings for the rest of the day. She said: \"You can get settled today. I''ll check in with you tomorrow.\"\n\nYour onboarding materials are complete. You have no assigned tasks. The office is open-plan and the team of seven is working.\n\nWhat the record shows: the team''s standing practices are on the shared drive, including a weekly planning meeting tomorrow morning; two analysts sit within speaking distance; the firm''s onboarding checklist asks a new starter to meet each team member within the first week; and nobody has been asked to induct you.", "reveals": [{"code": "R1", "text": "What do you state to anyone about what you are here to do?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you ask?", "role": "Information"}, {"code": "R3", "text": "What do you put forward for the rest of today?", "role": "Information"}, {"code": "R4", "text": "Is there anything in your own plan for the day you would change if it does not land?", "role": "Information"}, {"code": "R5", "text": "What happens tomorrow if nothing is assigned?", "role": "Information"}, {"code": "R6", "text": "Your manager writes next morning, \"I hear you told the team you''d shadow someone today. Who did you arrange that with?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three designated positions"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three designated enquiries"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three shared items"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Four available options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "R4 asks what would change"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A written response cannot evidence a route used"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "The source designates no available_routes item, so the bound question cannot be offered"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "The only source in the bank where an agreement is formed with no prior difference — a relationship that does not yet exist still produces a stated agreement or none"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "R5 asks about tomorrow"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "Exchange_test_point at R6"}], "material_map": [{"Item": "SI1", "Item text": "the weekly planning meeting tomorrow morning", "Where the participant meets it": "The situation", "Quoted text": "a weekly planning meeting tomorrow morning"}, {"Item": "SI2", "Item text": "the onboarding checklist is the firm''s, not one person''s", "Where the participant meets it": "The situation", "Quoted text": "the firm''s onboarding checklist asks a new starter"}, {"Item": "SI3", "Item text": "the shared drive holds the standing practices", "Where the participant meets it": "The situation", "Quoted text": "standing practices are on the shared drive"}], "source_sheet": {"d5_situation_class": "SC-D5-6", "workplace_demand": "Starting work on a first day where no task is assigned and no working relationship yet exists with the team.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The manager''s absence; the team''s availability or friendliness, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That waiting is passive or asking is forward; that a new starter should do either; anything about initiative.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "designated_positions": [{"id": "DP1", "text": "wait for the manager''s check-in tomorrow"}, {"id": "DP2", "text": "ask a team member for something to pick up today"}, {"id": "DP3", "text": "work the onboarding checklist independently today"}], "designated_enquiries": [{"id": "DE1", "text": "what the team is working on this week"}, {"id": "DE2", "text": "what the weekly planning meeting covers"}, {"id": "DE3", "text": "what a new analyst normally picks up first"}], "shared_items": [{"id": "SI1", "text": "the weekly planning meeting tomorrow morning"}, {"id": "SI2", "text": "the onboarding checklist is the firm''s, not one person''s"}, {"id": "SI3", "text": "the shared drive holds the standing practices"}], "available_options": [{"id": "AO1", "text": "attend tomorrow''s planning meeting"}, {"id": "AO2", "text": "work the checklist today and meet two team members"}, {"id": "AO3", "text": "ask a nearby analyst to shadow"}, {"id": "AO4", "text": "send the manager a note listing what has been done"}], "available_routes": [], "agreement_contents": [{"id": "AC1", "text": "what would be picked up"}, {"id": "AC2", "text": "with whom"}, {"id": "AC3", "text": "by when"}], "counterpart_role": "The team of seven and the manager.", "counterpart_position": "Nobody has been asked to induct the participant.", "difference_established": "No relationship and no assignment exists, established at the situation.", "authority_relation": "The manager is absent for the day.", "recording_route": "A note to the manager.", "persistence_point": "Tomorrow''s check-in.", "exchange_test_point": "R6", "list_note": "Not selectable in available_routes, because a written response cannot evidence a route used: directly to a team member; in writing to the manager; at tomorrow''s planning meeting (BR-D5-10 applies).", "source_note": null, "situation_class_label": "A working relationship to be formed where none exists", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D5-S1-002", "stage_code": "S1", "source_version_hash": "5d0b6db49c19b105a1af96075dc4ad77ab10306ed2f2435adf588f9169e10713", "serving_eligible": false, "verbatim": "It is your first day as a project analyst at a consulting firm. Your manager introduced you to the team this morning and left for client meetings for the rest of the day. She said: \"You can get settled today. I''ll check in with you tomorrow.\"\n\nYour onboarding materials are complete. You have no assigned tasks. The office is open-plan and the team of seven is working.\n\nWhat the record shows: the team''s standing practices are on the shared drive, including a weekly planning meeting tomorrow morning; two analysts sit within speaking distance; the firm''s onboarding checklist asks a new starter to meet each team member within the first week; and nobody has been asked to induct you."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S1-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S1-003', 'source'::public.t3a_content_family, 'THE STRATEGY PRESENTED WITHOUT YOU', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE STRATEGY PRESENTED WITHOUT YOU", "source_digest": "91bc73dbbb5e541c748fbe6b76bcc61c785c792f964d2a099a3e474dadc5f0bf", "situation": "For three weeks you and a colleague co-developed a client retention strategy. The work was split evenly: you did the customer segmentation analysis and the retention modeling; the colleague did the campaign design and the channel strategy.\n\nThis morning your colleague presented the strategy to the senior leadership team. You were not invited and were not named in the presentation.\n\nWhat the record shows: the project folder holds both workstreams with their authors and dates; the segmentation analysis and the retention model are yours and are dated; the invitation to present went to one person; and the strategy goes to the client next week under both names on the proposal cover.", "reveals": [{"code": "R1", "text": "What do you state as your own position on the authorship?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you ask?", "role": "Information"}, {"code": "R3", "text": "What do you put forward?", "role": "Information"}, {"code": "R4", "text": "Is there anything in your position you would change?", "role": "Information"}, {"code": "R5", "text": "If nothing changes, what happens before the client sees it next week?", "role": "Information"}, {"code": "R6", "text": "Your manager writes, \"You said you were fine with how the presentation went. Were you?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three designated positions"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three designated enquiries, all about the record rather than the colleague''s intent"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three shared items"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Four available options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "R4 asks what would change"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A written response cannot evidence a route used"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "The source designates no available_routes item, so the bound question cannot be offered"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The client deadline is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "Exchange_test_point at R6"}], "material_map": [{"Item": "SI1", "Item text": "the project folder records both workstreams with dates", "Where the participant meets it": "The situation", "Quoted text": "the project folder holds both workstreams with their authors and dates"}, {"Item": "SI2", "Item text": "the client proposal goes out under both names", "Where the participant meets it": "The situation", "Quoted text": "under both names on the proposal cover"}, {"Item": "SI3", "Item text": "the strategy is due with the client next week", "Where the participant meets it": "The situation", "Quoted text": "the strategy goes to the client next week"}], "source_sheet": {"d5_situation_class": "SC-D5-2", "workplace_demand": "Responding after a colleague presented jointly developed work to senior leadership without naming the participant.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The colleague''s motive, which the source does not establish and no record may supply.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the colleague took credit deliberately; that raising it is petty or letting it go is weak; anything about confidence.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "designated_positions": [{"id": "DP1", "text": "the authorship of both workstreams should be stated to leadership"}, {"id": "DP2", "text": "the cover of the client proposal is sufficient"}, {"id": "DP3", "text": "the matter should be raised before the client sees it, not after"}], "designated_enquiries": [{"id": "DE1", "text": "who issued the invitation to present"}, {"id": "DE2", "text": "what was said about authorship in the presentation"}, {"id": "DE3", "text": "what the client proposal cover will carry"}], "shared_items": [{"id": "SI1", "text": "the project folder records both workstreams with dates"}, {"id": "SI2", "text": "the client proposal goes out under both names"}, {"id": "SI3", "text": "the strategy is due with the client next week"}], "available_options": [{"id": "AO1", "text": "a short note to leadership stating both workstreams"}, {"id": "AO2", "text": "the authorship stated on the client proposal only"}, {"id": "AO3", "text": "a correction raised at the next team meeting"}, {"id": "AO4", "text": "nothing further"}], "available_routes": [], "agreement_contents": [{"id": "AC1", "text": "what is stated about authorship"}, {"id": "AC2", "text": "to whom"}, {"id": "AC3", "text": "before or after the client sees it"}], "counterpart_role": "The co-developing colleague.", "counterpart_position": null, "difference_established": "The presentation was given without the participant named, at the situation.", "authority_relation": "Peers, with a shared manager.", "recording_route": "The project folder and the proposal cover.", "persistence_point": "The client sees the strategy next week.", "exchange_test_point": "R6", "list_note": "Not selectable in available_routes, because a written response cannot evidence a route used: directly to the colleague; in writing to the manager; to the leadership team (BR-D5-10 applies).", "source_note": "counterpart_position: The source establishes no intent on the colleague''s part and no question may recover one.", "situation_class_label": "A contribution presented as another party''s", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D5-S1-003", "stage_code": "S1", "source_version_hash": "91bc73dbbb5e541c748fbe6b76bcc61c785c792f964d2a099a3e474dadc5f0bf", "serving_eligible": false, "verbatim": "For three weeks you and a colleague co-developed a client retention strategy. The work was split evenly: you did the customer segmentation analysis and the retention modeling; the colleague did the campaign design and the channel strategy.\n\nThis morning your colleague presented the strategy to the senior leadership team. You were not invited and were not named in the presentation.\n\nWhat the record shows: the project folder holds both workstreams with their authors and dates; the segmentation analysis and the retention model are yours and are dated; the invitation to present went to one person; and the strategy goes to the client next week under both names on the proposal cover."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S1-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S1-004', 'source'::public.t3a_content_family, 'THE REPLY TO THE GROUP THREAD', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE REPLY TO THE GROUP THREAD", "source_digest": "e2f6aab6f2f810e2cfd77ecd011bd92cb89e09f1570bed783b96687412a778e0", "situation": "Your team of five shares project updates on a group email thread. You proposed a change to the shipping schedule that the data shows would reduce late deliveries by about fifteen per cent.\n\nA colleague replied to the whole group: \"Interesting idea. Though I''m not sure how practical it is for those of us who actually handle the day-to-day logistics.\"\n\nWhat the record shows: the fifteen per cent figure comes from twelve months of delivery data held by the operations team; the proposed change alters the dispatch cut-off by ninety minutes; the colleague runs the afternoon dispatch; and the operations manager has asked for a recommendation by Friday.", "reveals": [{"code": "R1", "text": "What do you state as your own position?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you ask?", "role": "Information"}, {"code": "R3", "text": "What do you put forward?", "role": "Information"}, {"code": "R4", "text": "Is there anything in your proposal you would change?", "role": "Information"}, {"code": "R5", "text": "What happens if no recommendation is agreed by Friday?", "role": "Information"}, {"code": "R6", "text": "The operations manager writes, \"You said the ninety-minute change was agreed. Was it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three designated positions"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three designated enquiries"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three shared items"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Four available options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A written response cannot evidence a route used"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "The source designates no available_routes item, so the bound question cannot be offered"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "Friday is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "the twelve-month delivery data is the operations team''s", "Where the participant meets it": "The situation", "Quoted text": "twelve months of delivery data held by the operations team"}, {"Item": "SI2", "Item text": "the Friday recommendation applies to everyone", "Where the participant meets it": "The situation", "Quoted text": "asked for a recommendation by Friday"}, {"Item": "SI3", "Item text": "the late deliveries the proposed change would reduce", "Where the participant meets it": "The situation", "Quoted text": "would reduce late deliveries by about fifteen per cent"}], "source_sheet": {"d5_situation_class": "SC-D5-1", "workplace_demand": "Replying on a group thread where a colleague has questioned the practicality of a schedule change the participant proposed.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The colleague''s tone or intent, never observed or recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the reply was hostile, fair or undermining; that replying in the thread is better than replying privately; anything about composure.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "designated_positions": [{"id": "DP1", "text": "the ninety-minute cut-off change as proposed"}, {"id": "DP2", "text": "a shorter cut-off change trialled on one route"}, {"id": "DP3", "text": "no change until the afternoon dispatch position is understood"}], "designated_enquiries": [{"id": "DE1", "text": "what the ninety-minute change would do to the afternoon dispatch"}, {"id": "DE2", "text": "what the day-to-day handling requires that the data does not show"}, {"id": "DE3", "text": "what a trial would need to be workable"}], "shared_items": [{"id": "SI1", "text": "the twelve-month delivery data is the operations team''s"}, {"id": "SI2", "text": "the Friday recommendation applies to everyone"}, {"id": "SI3", "text": "the late deliveries the proposed change would reduce"}], "available_options": [{"id": "AO1", "text": "trial on one route"}, {"id": "AO2", "text": "reduce the change from ninety to forty-five minutes"}, {"id": "AO3", "text": "defer to after the next data cycle"}, {"id": "AO4", "text": "recommend as proposed"}], "available_routes": [], "agreement_contents": [{"id": "AC1", "text": "the cut-off change"}, {"id": "AC2", "text": "whether trialled"}, {"id": "AC3", "text": "the recommendation to Friday"}], "counterpart_role": "The colleague who runs the afternoon dispatch.", "counterpart_position": "The change is impractical for day-to-day handling.", "difference_established": "The reply to the group thread, at the situation.", "authority_relation": "Peers; the operations manager decides.", "recording_route": "The group thread and the Friday recommendation.", "persistence_point": "Friday.", "exchange_test_point": "R6", "list_note": "Not selectable in available_routes, because a written response cannot evidence a route used: reply to the group thread; directly to the colleague; to the operations manager (BR-D5-10 applies).", "source_note": "counterpart_position: The library original asks the mentor whether the reply was PASSIVE-AGGRESSIVE. that question is removed and cannot be restored.", "situation_class_label": "Two parties holding different positions on a decision both must work under", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D5-S1-004", "stage_code": "S1", "source_version_hash": "e2f6aab6f2f810e2cfd77ecd011bd92cb89e09f1570bed783b96687412a778e0", "serving_eligible": false, "verbatim": "Your team of five shares project updates on a group email thread. You proposed a change to the shipping schedule that the data shows would reduce late deliveries by about fifteen per cent.\n\nA colleague replied to the whole group: \"Interesting idea. Though I''m not sure how practical it is for those of us who actually handle the day-to-day logistics.\"\n\nWhat the record shows: the fifteen per cent figure comes from twelve months of delivery data held by the operations team; the proposed change alters the dispatch cut-off by ninety minutes; the colleague runs the afternoon dispatch; and the operations manager has asked for a recommendation by Friday."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S1-004' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S1-005', 'source'::public.t3a_content_family, 'THE CO-LEAD''S SECTIONS AT DAY NINE', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE CO-LEAD''S SECTIONS AT DAY NINE", "source_digest": "e0d4b6b9d221804b34b36e7d83e334daf77dc76ab908f2b2e847f4ea7362e55d", "situation": "You and a colleague were assigned as co-leads on a market analysis report due next Friday. The work was divided at the start: you handle the competitive landscape and financial projections, the colleague handles the customer survey analysis and recommendations.\n\nIt is Wednesday, day nine of fourteen. Your sections are complete. The colleague''s sections are not started, and the shared folder holds no draft.\n\nWhat the record shows: the division of work is in the project note both of you signed; the survey data the colleague needs was delivered on day four; five working days remain; and the client presentation is booked for the Monday after the deadline.", "reveals": [{"code": "R1", "text": "What do you state as your own position on the remaining work?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you ask?", "role": "Information"}, {"code": "R3", "text": "What do you put forward?", "role": "Information"}, {"code": "R4", "text": "Is there anything in your own position you would change?", "role": "Information"}, {"code": "R5", "text": "If the sections are still not started on Friday, what happens?", "role": "Information"}, {"code": "R6", "text": "Your manager writes, \"You told me you''d take on the survey analysis. Did you say that?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three designated positions"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three designated enquiries, all about the work rather than the reason"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three shared items"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Four available options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A written response cannot evidence a route used"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "The source designates no available_routes item, so the bound question cannot be offered"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "Friday and the Monday presentation"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "the signed project note holds the division", "Where the participant meets it": "The situation", "Quoted text": "the division of work is in the project note both of you signed"}, {"Item": "SI2", "Item text": "the client presentation is booked for both", "Where the participant meets it": "The situation", "Quoted text": "the client presentation is booked for the Monday after the deadline"}, {"Item": "SI3", "Item text": "five working days remain for both", "Where the participant meets it": "The situation", "Quoted text": "five working days remain"}], "source_sheet": {"d5_situation_class": "SC-D5-4", "workplace_demand": "Working with a co-lead whose sections of a shared deliverable are not started at day nine of a two-week schedule.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The co-lead''s circumstances or conduct, never recorded or rendered.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the co-lead failed, which is A D2 matter and not observed here; that taking the work on is generous or enabling; anything about fairness.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "designated_positions": [{"id": "DP1", "text": "the division in the signed project note stands"}, {"id": "DP2", "text": "the participant takes one of the two outstanding sections"}, {"id": "DP3", "text": "the deadline moves and the client presentation with it"}], "designated_enquiries": [{"id": "DE1", "text": "what remains to be done on the two sections"}, {"id": "DE2", "text": "what would be needed for them to land by Friday"}, {"id": "DE3", "text": "whether the survey data as delivered is usable"}], "shared_items": [{"id": "SI1", "text": "the signed project note holds the division"}, {"id": "SI2", "text": "the client presentation is booked for both"}, {"id": "SI3", "text": "five working days remain for both"}], "available_options": [{"id": "AO1", "text": "take the survey analysis"}, {"id": "AO2", "text": "take the recommendations"}, {"id": "AO3", "text": "request a deadline move together"}, {"id": "AO4", "text": "hold to the signed division"}], "available_routes": [], "agreement_contents": [{"id": "AC1", "text": "who does the outstanding sections"}, {"id": "AC2", "text": "by when"}, {"id": "AC3", "text": "what goes to the manager"}], "counterpart_role": "The co-lead.", "counterpart_position": null, "difference_established": "Day nine with two sections not started, at the situation.", "authority_relation": "Co-leads, with a shared manager.", "recording_route": "The project note.", "persistence_point": "Friday, then the Monday presentation.", "exchange_test_point": "R6", "list_note": "Not selectable in available_routes, because a written response cannot evidence a route used: directly to the co-lead; in writing to the manager; jointly to the manager (BR-D5-10 applies).", "source_note": "counterpart_position: The source establishes no reason for the sections not being started and no question may recover one.", "situation_class_label": "Divided work not arriving from one side", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D5-S1-005", "stage_code": "S1", "source_version_hash": "e0d4b6b9d221804b34b36e7d83e334daf77dc76ab908f2b2e847f4ea7362e55d", "serving_eligible": false, "verbatim": "You and a colleague were assigned as co-leads on a market analysis report due next Friday. The work was divided at the start: you handle the competitive landscape and financial projections, the colleague handles the customer survey analysis and recommendations.\n\nIt is Wednesday, day nine of fourteen. Your sections are complete. The colleague''s sections are not started, and the shared folder holds no draft.\n\nWhat the record shows: the division of work is in the project note both of you signed; the survey data the colleague needs was delivered on day four; five working days remain; and the client presentation is booked for the Monday after the deadline."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S1-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S1-006', 'source'::public.t3a_content_family, 'THE PROPOSAL THE ROOM PUSHED BACK ON', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE PROPOSAL THE ROOM PUSHED BACK ON", "source_digest": "352481e492343e77f771a5199aa55007403a9e53feb7fc8695974b907638cba9", "situation": "You spent two weeks developing a proposal to streamline the client reporting process. Your analysis shows the current process takes about twelve hours per reporting cycle; the proposed workflow would take about seven.\n\nYou presented at the weekly team meeting. A senior analyst said something similar had been tried before. Another said the numbers looked optimistic. A third asked who would carry the transition work.\n\nWhat the record shows: the twelve-hour figure comes from four cycles timed by you; the seven-hour figure is modelled and not yet observed; the earlier attempt was three years ago and is not documented; and the department head has asked for a decision at next month''s meeting.", "reveals": [{"code": "R1", "text": "What do you state as your own position?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you ask?", "role": "Information"}, {"code": "R3", "text": "What do you put forward?", "role": "Information"}, {"code": "R4", "text": "Is there anything in your position you would change?", "role": "Information"}, {"code": "R5", "text": "What happens if no decision is reached next month?", "role": "Information"}, {"code": "R6", "text": "The department head writes, \"You said the seven hours was measured. Was it?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three designated positions"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three designated enquiries"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three shared items"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Four available options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "R4 asks what would change"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A written response cannot evidence a route used"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "The source designates no available_routes item, so the bound question cannot be offered"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "Next month''s decision"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "Test point at R6"}], "material_map": [{"Item": "SI1", "Item text": "the current reporting process", "Where the participant meets it": "The situation", "Quoted text": "the current process takes about twelve hours"}, {"Item": "SI2", "Item text": "the twelve-hour figure, which comes from four timed cycles", "Where the participant meets it": "The situation", "Quoted text": "the twelve-hour figure comes from four cycles timed by you"}, {"Item": "SI3", "Item text": "the decision point is next month for everyone", "Where the participant meets it": "The situation", "Quoted text": "a decision at next month''s meeting"}], "source_sheet": {"d5_situation_class": "SC-D5-1", "workplace_demand": "Following up a proposal that three colleagues questioned in a team meeting, before next month''s decision.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The three colleagues'' reasoning or standing, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the room was obstructive or the participant under-prepared; that any option is correct; anything about persuasion.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "designated_positions": [{"id": "DP1", "text": "the workflow as proposed"}, {"id": "DP2", "text": "a measured pilot on one reporting cycle before any decision"}, {"id": "DP3", "text": "no change until the transition work is resourced"}], "designated_enquiries": [{"id": "DE1", "text": "what the earlier attempt involved"}, {"id": "DE2", "text": "what would make the modelled figure credible"}, {"id": "DE3", "text": "who could carry the transition work"}], "shared_items": [{"id": "SI1", "text": "the current reporting process"}, {"id": "SI2", "text": "the twelve-hour figure, which comes from four timed cycles"}, {"id": "SI3", "text": "the decision point is next month for everyone"}], "available_options": [{"id": "AO1", "text": "pilot one cycle and measure"}, {"id": "AO2", "text": "present the modelled figure as modelled and seek a decision anyway"}, {"id": "AO3", "text": "resource the transition work first"}, {"id": "AO4", "text": "withdraw the proposal"}], "available_routes": [], "agreement_contents": [{"id": "AC1", "text": "whether a pilot runs"}, {"id": "AC2", "text": "who carries the transition"}, {"id": "AC3", "text": "what goes to the department head"}], "counterpart_role": "Three colleagues in the meeting.", "counterpart_position": "It has been tried, the numbers look optimistic, and the transition work is unassigned.", "difference_established": "The three responses in the meeting, at the situation.", "authority_relation": "The department head decides.", "recording_route": "The team meeting note.", "persistence_point": "Next month''s decision.", "exchange_test_point": "R6", "list_note": "Not selectable in available_routes, because a written response cannot evidence a route used: the team meeting; individually before next month; to the department head (BR-D5-10 applies).", "source_note": "Exchange test point: IT puts an assertion the record contradicts — the seven-hour figure is modelled, not measured — so A3 is reachable.", "situation_class_label": "Two parties holding different positions on a decision both must work under", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D5-S1-006", "stage_code": "S1", "source_version_hash": "352481e492343e77f771a5199aa55007403a9e53feb7fc8695974b907638cba9", "serving_eligible": false, "verbatim": "You spent two weeks developing a proposal to streamline the client reporting process. Your analysis shows the current process takes about twelve hours per reporting cycle; the proposed workflow would take about seven.\n\nYou presented at the weekly team meeting. A senior analyst said something similar had been tried before. Another said the numbers looked optimistic. A third asked who would carry the transition work.\n\nWhat the record shows: the twelve-hour figure comes from four cycles timed by you; the seven-hour figure is modelled and not yet observed; the earlier attempt was three years ago and is not documented; and the department head has asked for a decision at next month''s meeting."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S1-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S1-008', 'source'::public.t3a_content_family, 'ONE PLATFORM, TWO BOOKINGS', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "ONE PLATFORM, TWO BOOKINGS", "source_digest": "c6b922fdcaf1c0936d498c41f0511a16e16744fcfec42b9ebabd852b3051cf96", "situation": "Your team has been allocated the company''s data analytics platform for a client campaign launching in three weeks. The platform runs one major analysis project at a time.\n\nYou have just learned that the sales team has booked the same platform for the same two-week window, for a quarterly pipeline forecast.\n\nWhat the record shows: both bookings are in the shared calendar and neither was flagged as a clash; your campaign launch date is contractual with the client; the pipeline forecast is due to the executive team on a date one week after your launch; the platform administrator can split the window into two one-week blocks; and a one-week block is enough for neither project in full.", "reveals": [{"code": "R1", "text": "What do you state as your own position on the window?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you ask?", "role": "Information"}, {"code": "R3", "text": "What do you put forward?", "role": "Information"}, {"code": "R4", "text": "Is there anything in your own claim you would change?", "role": "Information"}, {"code": "R5", "text": "If no arrangement is reached, what happens?", "role": "Information"}, {"code": "R6", "text": "The platform administrator writes, \"You said the other team had agreed to move. Had they?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three designated positions"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three designated enquiries"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three shared items, including the constraint that binds both"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Four available options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Ao-03 is a reduction of the participant''s own claim"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A written response cannot evidence a route used"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "The source designates no available_routes item, so the bound question cannot be offered"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "both bookings are in the shared calendar", "Where the participant meets it": "The situation", "Quoted text": "both bookings are in the shared calendar"}, {"Item": "SI2", "Item text": "the platform runs one project at a time", "Where the participant meets it": "The situation", "Quoted text": "platform runs one major analysis project at a time"}, {"Item": "SI3", "Item text": "neither project fits a one-week block in full", "Where the participant meets it": "The situation", "Quoted text": "a one-week block is enough for neither project in full"}], "source_sheet": {"d5_situation_class": "SC-D5-3", "workplace_demand": "Settling with another team how a shared platform booked twice for the same window is used.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The sales team''s conduct or claim''s merit, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the campaign''s contractual date outranks the forecast; that conceding the window is weak; anything about negotiation.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "designated_positions": [{"id": "DP1", "text": "the campaign holds the full window on the contractual launch"}, {"id": "DP2", "text": "the window splits into two one-week blocks"}, {"id": "DP3", "text": "the campaign moves to the week after the forecast"}], "designated_enquiries": [{"id": "DE1", "text": "what the forecast needs the platform for and for how long"}, {"id": "DE2", "text": "what a one-week block would deliver for each"}, {"id": "DE3", "text": "what the administrator can offer"}], "shared_items": [{"id": "SI1", "text": "both bookings are in the shared calendar"}, {"id": "SI2", "text": "the platform runs one project at a time"}, {"id": "SI3", "text": "neither project fits a one-week block in full"}], "available_options": [{"id": "AO1", "text": "split into two one-week blocks"}, {"id": "AO2", "text": "the campaign takes the window and the forecast moves"}, {"id": "AO3", "text": "the campaign reduces its analysis scope to fit one week"}, {"id": "AO4", "text": "refer the clash to the administrator to decide"}], "available_routes": [], "agreement_contents": [{"id": "AC1", "text": "how the window divides"}, {"id": "AC2", "text": "which dates each holds"}, {"id": "AC3", "text": "who tells the administrator"}], "counterpart_role": "The sales team lead.", "counterpart_position": "The forecast needs the window.", "difference_established": "Two bookings on one window, at the situation.", "authority_relation": "The platform administrator controls allocation; neither party has authority over the other.", "recording_route": "The shared calendar.", "persistence_point": "The window opens and the clash stands.", "exchange_test_point": "R6", "list_note": "Not selectable in available_routes, because a written response cannot evidence a route used: directly to the sales team lead; to the platform administrator; in writing to both managers (BR-D5-10 applies).", "source_note": null, "situation_class_label": "A resource claimed by two parties that cannot serve both", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D5-S1-008", "stage_code": "S1", "source_version_hash": "c6b922fdcaf1c0936d498c41f0511a16e16744fcfec42b9ebabd852b3051cf96", "serving_eligible": false, "verbatim": "Your team has been allocated the company''s data analytics platform for a client campaign launching in three weeks. The platform runs one major analysis project at a time.\n\nYou have just learned that the sales team has booked the same platform for the same two-week window, for a quarterly pipeline forecast.\n\nWhat the record shows: both bookings are in the shared calendar and neither was flagged as a clash; your campaign launch date is contractual with the client; the pipeline forecast is due to the executive team on a date one week after your launch; the platform administrator can split the window into two one-week blocks; and a one-week block is enough for neither project in full."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S1-008' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S1-010', 'source'::public.t3a_content_family, 'TWO APPROACHES TO ONE PROPOSAL', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "TWO APPROACHES TO ONE PROPOSAL", "source_digest": "07c5aa97758b43f326d42bb33e85e1ee3a8153918efc3f68744a72b17e617622", "situation": "You and a colleague have been assigned to co-write a proposal for a new client engagement. It is due in one week and the client is a conservative financial services firm.\n\nYou have documented preferences that differ. Yours is a structured, data-heavy proposal: clear sections, detailed financial projections, risk analysis, conservative estimates. Your colleague''s is a narrative-led proposal: a story arc, fewer figures, emphasis on vision.\n\nWhat the record shows: the client''s request for proposal asks for a risk section and three-year projections; it sets no limit on narrative content; the firm''s proposal template carries both a narrative summary and a projections appendix; and the deadline is one week with no extension available.", "reveals": [{"code": "R1", "text": "What do you state as your own position on the structure?", "role": "Opening"}, {"code": "R2", "text": "What, if anything, do you ask?", "role": "Information"}, {"code": "R3", "text": "What do you put forward?", "role": "Information"}, {"code": "R4", "text": "Is there anything in your own approach you would change?", "role": "Information"}, {"code": "R5", "text": "If you cannot settle the structure, what happens?", "role": "Information"}, {"code": "R6", "text": "Your manager writes, \"You said you''d agreed to drop the projections. Did you?\" What do you say?", "role": "Account test"}], "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three designated positions"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three designated enquiries"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three shared items, including a requirement that binds both"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Four available options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Ao-02 and ao-03 both change the participant''s own approach"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "The source where proposing and moving are most likely to select the same option, so st-D5-048 composes and the two determinations must not be merged"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A written response cannot evidence a route used"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "The source designates no available_routes item, so the bound question cannot be offered"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The deadline is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "Test point at R6"}], "material_map": [{"Item": "SI1", "Item text": "the request for proposal requires a risk section and three-year projections", "Where the participant meets it": "The situation", "Quoted text": "asks for a risk section and three-year projections"}, {"Item": "SI2", "Item text": "the firm''s template carries both forms", "Where the participant meets it": "The situation", "Quoted text": "the firm''s proposal template carries both"}, {"Item": "SI3", "Item text": "one week with no extension binds both", "Where the participant meets it": "The situation", "Quoted text": "the deadline is one week with no extension"}], "source_sheet": {"d5_situation_class": "SC-D5-1", "workplace_demand": "Agreeing an approach with a co-author whose documented preference for one proposal differs, with a week and no extension.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The co-author''s preference or reasoning, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That either approach suits the client better; that accommodating is flexible or holding firm is rigid; anything about style.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "designated_positions": [{"id": "DP1", "text": "the structured, data-led form throughout"}, {"id": "DP2", "text": "the firm''s template, carrying both a narrative summary and a projections appendix"}, {"id": "DP3", "text": "the narrative-led form with the required risk and projection sections added"}], "designated_enquiries": [{"id": "DE1", "text": "what the narrative form is intended to carry"}, {"id": "DE2", "text": "what the client''s request for proposal requires by name"}, {"id": "DE3", "text": "what the firm''s template already provides"}], "shared_items": [{"id": "SI1", "text": "the request for proposal requires a risk section and three-year projections"}, {"id": "SI2", "text": "the firm''s template carries both forms"}, {"id": "SI3", "text": "one week with no extension binds both"}], "available_options": [{"id": "AO1", "text": "use the firm''s template as it stands"}, {"id": "AO2", "text": "narrative summary first, projections appendix behind"}, {"id": "AO3", "text": "split authorship by section"}, {"id": "AO4", "text": "one form throughout, decided by the other party"}], "available_routes": [], "agreement_contents": [{"id": "AC1", "text": "the structure"}, {"id": "AC2", "text": "who writes which section"}, {"id": "AC3", "text": "by when each part lands"}], "counterpart_role": "The co-author.", "counterpart_position": "A narrative-led proposal with fewer figures.", "difference_established": "The two documented preferences, at the situation.", "authority_relation": "Co-authors with equal standing.", "recording_route": "The proposal outline in the shared folder.", "persistence_point": "The one-week deadline with no extension.", "exchange_test_point": "R6", "list_note": "Not selectable in available_routes, because a written response cannot evidence a route used: directly to the co-author; in writing to the manager; to the client for clarification (BR-D5-10 applies).", "source_note": null, "situation_class_label": "Two parties holding different positions on a decision both must work under", "observation_mode_label": "written_response", "min_seconds": 360, "max_seconds": 1500}, "source_identifier": "SRC-D5-S1-010", "stage_code": "S1", "source_version_hash": "07c5aa97758b43f326d42bb33e85e1ee3a8153918efc3f68744a72b17e617622", "serving_eligible": false, "verbatim": "You and a colleague have been assigned to co-write a proposal for a new client engagement. It is due in one week and the client is a conservative financial services firm.\n\nYou have documented preferences that differ. Yours is a structured, data-heavy proposal: clear sections, detailed financial projections, risk analysis, conservative estimates. Your colleague''s is a narrative-led proposal: a story arc, fewer figures, emphasis on vision.\n\nWhat the record shows: the client''s request for proposal asks for a risk section and three-year projections; it sets no limit on narrative content; the firm''s proposal template carries both a narrative summary and a projections appendix; and the deadline is one week with no extension available."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S1-010' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S2-001', 'source'::public.t3a_content_family, 'THE IDEA ANNOUNCED UNDER ANOTHER NAME', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE IDEA ANNOUNCED UNDER ANOTHER NAME", "source_digest": "b8138729d89f37711ac75764bfc7c379aad15efce31e83bf748762a6ccccd6c9", "mentor_brief": "The mentor reads the scripted lines of the director. the mentor forms no view of the colleague or the director and records nothing about either. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say.", "participant_pre_brief": "Three weeks ago, in a brainstorming session, you proposed a social media strategy built around client success stories. This morning your director announced a strategy of that description as a colleague''s work. What the record shows: the brainstorm has a circulated note listing contributions by name, and yours is on it; the strategy launches in two weeks; the launch materials have not yet been written; and the director has asked you to support the launch.", "script": [{"beat": "B1", "type": "SAY", "spoken": "You have heard the announcement. I would like to know where you are with it. I will let you start.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where do you stand on this?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you putting forward, and what would you move on?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What would be agreed, and what if it is not?", "direction": "Read once, verbatim.", "capture": [{"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have it right — you said the brainstorm note names you. Does it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. That is the end of the session.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents and a recording route"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The launch is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "Test point at B6"}], "material_map": [{"Item": "SI1", "Item text": "the circulated brainstorm note", "Where the participant meets it": "The pre-brief", "Quoted text": "the brainstorm has a circulated note listing contributions by name"}, {"Item": "SI2", "Item text": "the two-week launch date", "Where the participant meets it": "The pre-brief", "Quoted text": "the strategy launches in two weeks"}, {"Item": "SI3", "Item text": "the unwritten launch materials", "Where the participant meets it": "The pre-brief", "Quoted text": "the launch materials have not yet been written"}], "source_sheet": {"d5_situation_class": "SC-D5-2", "workplace_demand": "Speaking with a director about an idea the record attributes to the participant that was announced as a colleague''s work.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; which route was used; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The colleague''s or director''s conduct, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the colleague took the idea; that raising it is petty; anything about confidence.", "compatibility_class": "S2-SEVEN-BEAT", "designated_positions": [{"id": "DP1", "text": "the brainstorm note''s record of contribution should be stated"}, {"id": "DP2", "text": "the launch proceeds and the record is corrected afterwards"}, {"id": "DP3", "text": "the launch materials carry both names"}], "designated_enquiries": [{"id": "DE1", "text": "what the announced strategy contains"}, {"id": "DE2", "text": "what the brainstorm note records"}, {"id": "DE3", "text": "what the launch materials will say"}], "shared_items": [{"id": "SI1", "text": "the circulated brainstorm note"}, {"id": "SI2", "text": "the two-week launch date"}, {"id": "SI3", "text": "the unwritten launch materials"}], "available_options": [{"id": "AO1", "text": "both names on the launch materials"}, {