  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S2-002', 'source'::public.t3a_content_family, 'THE MIGRATION YOU CANNOT INSTRUCT', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE MIGRATION YOU CANNOT INSTRUCT", "source_digest": "d35789634d85b8911cc52bfb90e6094cb91bd0d3a91f24e80c05e68e0e538666", "mentor_brief": "The mentor reads the scripted lines of the technology team lead, verbatim, and forms no view of them. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say.", "participant_pre_brief": "Your manager has asked you to get the technology department to prioritize a system migration your team needs completed by month-end. Technology reports to a different executive, holds its own priorities, and you have no authority over it. You are meeting the technology team lead. What the record shows: the migration is estimated at nine working days of technology effort; technology''s current queue holds two items ahead of it, both with named business owners; month-end is fifteen working days away; and a partial migration covering the two highest-volume record sets is possible in four days.", "script": [{"beat": "B1", "type": "SAY", "spoken": "You have asked for time on the migration. My queue is what it is. I will let you put it to me.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "