  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S2-003', 'source'::public.t3a_content_family, 'FOUR PEOPLE AND THREE DEPARTURES', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "FOUR PEOPLE AND THREE DEPARTURES", "source_digest": "20752ad47643b01ba846e295534a0013a4a43bb15c45e48f0482f2194c8dc846", "mentor_brief": "The mentor reads the scripted lines of one remaining colleague and forms no view of them. The mentor reads the scripted lines verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the participant says or does not say.", "participant_pre_brief": "Your manager has announced that three positions on your team have been eliminated and those colleagues leave at the end of this week. Four of you remain and their work must be redistributed. What the record shows: the three departing workloads are documented in the team''s work register; two of the four remaining people are already at full allocation per that register; one of the three workloads is a client-facing account with a monthly review; the redistribution decision sits with the four remaining people to propose and the manager to approve; and a temporary contractor budget exists for one role for three months.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have to come back to the manager with a split. I will let you start.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"