  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE CONVERSATION NEITHER PARTY HAS OPENED", "source_digest": "f6e998b1ed23f35faa4105b9b9c3a1787982677ea77535897ae5b54aa311c043", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You lead a team of eight. One agent''s metrics have declined over six weeks: resolution times forty per cent above team average, satisfaction down from 4.3 to 3.5, two client complaints forwarded to you. They have missed no shifts. Your operations manager says the numbers have to come up. What the record shows: the six-week window and the three figures; that no cause has been established; that the company''s process requires a documented conversation before any formal step; that a support referral route exists and has not been offered; and that the agent has not raised anything with you."}], "submission_instructions": "Produce the position you would take into the conversation; what you would ask; what you would propose and what you would move on; and what would be agreed, recorded and taken forward if nothing changes. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Q-D5-02 is the element this source exercises best — the enquiries are the only route to a cause the source does not establish"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Q-D5-02 is the element this source exercises best — the enquiries are the only route to a cause the source does not establish"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Q-D5-02 is the element this source exercises best — the enquiries are the only route to a cause the source does not establish"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Q-D5-02 is the element this source exercises best — the enquiries are the only route to a cause the source does not establish"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Q-D5-02 is the element this source exercises best — the enquiries are the only route to a cause the source does not establish"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A route the submission names is proposed, not used"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "The source designates no available_routes item, so the bound question cannot be offered"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents and a real filed recording route"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The formal step is the persistence point"}, {"question": "Q-D5-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "SI1", "Item text": "the six-week figures, visible to both", "Where the participant meets it": "Pack document D1", "Quoted text": "the six-week window and the three figures"}, {"Item": "SI2", "Item text": "the documented process requiring a conversation first", "Where the participant meets it": "Pack document D1", "Quoted text": "the company''s process requires a documented conversation before any formal step"}, {"Item": "SI3", "Item text": "the support referral route, available to both", "Where the participant meets it": "Pack document D1", "Quoted text": "a support referral route exists"}], "source_sheet": {"d5_situation_class": "SC-D5-4", "workplace_demand": "Preparing a documented conversation with a team member about six weeks of recorded figures with no cause established.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; whether an agreement and its recording were stated; what was stated about the difference continuing.", "irrelevant_conduct": "The agent''s performance itself, which is the condition of the situation and never the record.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": "SENSITIVE_CONTENT", "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "Any conclusion about the agent, their capability or their circumstances; that a supportive or a firm approach is better; anything about management.", "compatibility_class": "S3-ASYNC-SUBMISSION", "designated_positions": [{"id": "DP1", "text": "the conversation establishes what has changed before anything else"}, {"id": "DP2", "text": "the figures and the process step are stated at the outset"}, {"id": "DP3", "text": "the support referral is offered before any formal step"}], "designated_enquiries": [{"id": "DE1", "text": "what has changed in the work over the six weeks"}, {"id": "DE2", "text": "what support would make a difference"}, {"id": "DE3", "text": "what the agent understands the figures to show"}], "shared_items": [{"id": "SI1", "text": "the six-week figures, visible to both"}, {"id": "SI2", "text": "the documented process requiring a conversation first"}, {"id": "SI3", "text": "the support referral route, available to both"}], "available_options": [{"id": "AO1", "text": "a support referral"}, {"id": "AO2", "text": "a documented review at four weeks"}, {"id": "AO3", "text": "a temporary change in the work mix"}, {"id": "AO4", "text": "the formal step after the conversation"}], "available_routes": [], "agreement_contents": [{"id": "AC1", "text": "what changes"}, {"id": "AC2", "text": "by when"}, {"id": "AC3", "text": "what is filed"}], "counterpart_role": "The agent.", "counterpart_position": null, "difference_established": "The figures against the team average, and the manager''s instruction.", "authority_relation": "The participant leads the agent; the operations manager leads the participant.", "recording_route": "The filed written summary.", "persistence_point": "The formal step if nothing changes.", "list_note": "Not selectable in available_routes, because a route a submission names is proposed, not used: a one-to-one conversation; a written summary filed after it; through the people function.", "source_note": "Higher review standard: This source concerns an exchange with a colleague whose performance figures are in issue. the colleague is A counterpart, never A subject. No question observes them, no statement names them, and no rendered sentence may characterise their work or circumstances. It must not be approved without the fairness drafting test discharged by someone who has read this note. counterpart_position: No question recovers the agent''s circumstances and no statement may supply them. Shared Stage 3 submission with SRC-D4-S3-004; one served instance, a separate observation record in each dimension.", "situation_class_label": "Divided work not arriving from one side", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D5-S3-004", "stage_code": "S3", "source_version_hash": "f6e998b1ed23f35faa4105b9b9c3a1787982677ea77535897ae5b54aa311c043", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S3-004' and family = 'source'::public.t3a_content_family;
