  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE FLAG THE PRIORITY CUTS AGAINST", "source_digest": "b698b2fda89220c7a70f39b29d0150a60b42793673d2d636ba0e0d41b336ed7c", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You coordinate compliance at a wealth management firm. A quarterly transaction report shows a pattern in one senior advisor''s portfolio: fourteen trades in a single client account over three months, with turnover high relative to the stated objective. What the record shows: the firm''s procedure requires any suitability flag to be documented and escalated within five business days of identification; you identified the pattern yesterday; the chief compliance officer has stated that maintaining a clean record ahead of next quarter''s examination is a strategic priority; nothing about intent or client instruction is established; and the chief compliance officer holds the escalation route and you have no authority to bypass it."}], "submission_instructions": "Produce the position you would put to the chief compliance officer; what you would ask; what you would propose and what you would move on; and what would be agreed, recorded and taken forward if it is not. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A route the submission names is proposed, not used"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "The source designates no available_routes item, so the bound question cannot be offered"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "External counsel is the authority"}, {"question": "Q-D5-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "SI1", "Item text": "the written procedure, which binds both", "Where the participant meets it": "Pack document D1", "Quoted text": "the firm''s procedure requires any suitability flag to be documented"}, {"Item": "SI2", "Item text": "the five-business-day clock, already running", "Where the participant meets it": "Pack document D1", "Quoted text": "within five business days of identification"}, {"Item": "SI3", "Item text": "the examination next quarter, which matters to both", "Where the participant meets it": "Pack document D1", "Quoted text": "ahead of next quarter''s examination"}], "source_s