  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE TEAM THAT HAS NOT WORKED TOGETHER", "source_digest": "e57e4dd463078b2ab0e0065c4916119eb4c7822d228c72bd95d7c0357ae5bde3", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You have been asked to stand up a working group drawn from four functions that have not collaborated before. The group has a twelve-week remit and one deliverable. What the record shows: each function has nominated one person and none has been told what the others'' remits are; two of the four functions have competing internal deadlines inside the twelve weeks; the remit document names the deliverable and the date and nothing about how the group works; no chair has been named; and the sponsor has said the group should settle its own working arrangement in the first two weeks."}], "submission_instructions": "Produce the position you would put to the group at its first meeting; what you would ask each member; what you would propose and what you would move on; and what would be agreed, recorded and taken forward if no arrangement holds. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A route the submission names is proposed, not used"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "The source designates no available_routes item, so the bound question cannot be offered"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The two-week point is the persistence point"}, {"question": "Q-D5-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "SI1", "Item text": "the remit document, held by all four", "Where the participant meets it": "Pack document D1", "Quoted text": "the remit document names the deliverable and the date"}, {"Item": "SI2", "Item text": "the twelve-week period, binding on all", "Where the participant meets it": "Pack document D1", "Quoted text": "has a twelve-week remit and one deliverable"}, {"Item": "SI3", "Item text": "the sponsor''s instruction to settle the arrangement in two weeks", "Where the participant meets it": "Pack document D1", "Quoted text": "settle its own working arrangement in the first two weeks"}], "source_sheet": {"d5_situation_class": "SC-D5-6", "workplace_demand": "Preparing how four functions that have not worked together start working as one team with no named chair.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; whether an agreement and its recording were stated; what was stated about the difference continuing.", "irrelevant_conduct": "The other nominees'' functions, availability or conduct, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "That a chair is better than none; that any function''s deadline outranks another''s; anything about leadership.", "compatibility_class": "S3-ASYNC-SUBMISSION", "designated_positions": [{"id": "DP1", "text": "the group names a chair in the first meeting"}, {"id": "DP2", "text": "the group works without a chair on a written cadence"}, {"id": "DP3", "text": "the sponsor is asked to name a chair"}], "designated_enquiries": [{"id": "DE1", "text": "what each function''s internal deadlines are inside the twelve weeks"}, {"id": "DE2", "text": "what each member understands the deliverable to be"}, {"id": "DE3", "text": "what working arrangements each function normally uses"}], "shared_items": [{"id": "SI1", "text": "the remit document, held by all four"}, {"id": "SI2", "text": "the twelve-week period, binding on all"}, {"id": "SI3", "text": "the sponsor''s instruction to settle the arrangement in two weeks"}], "available_options": [{"id": "AO1", "text": "a named chair"}, {"id": "AO2", "text": "a rotating chair by workstream"}, {"id": "AO3", "text": "a written cadence with no chair"}, {"id": "AO4", "text": "the sponsor decides"}], "available_routes": [], "agreement_contents": [{"id": "AC1", "text": "the working arrangement"}, {"id": "AC2", "text": "who holds which part"}, {"id": "AC3", "text": "the cadence and the record"}], "counterpart_role": "The three other function nominees.", "counterpart_position": null, "difference_established": "Four functions, no prior collaboration, no named chair, competing internal deadlines.", "authority_relation": "The sponsor holds the remit; no member leads another.", "recording_route": "The circulated working arrangement.", "persistence_point": "The two-week point, then the twelve-week deliverable.", "list_note": "Not selectable in available_routes, because a route a submission names is proposed, not used: the first meeting; a written arrangement circulated for agreement; to the sponsor.", "source_note": null, "situation_class_label": "A working relationship to be formed where none exists", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D5-S3-006", "stage_code": "S3", "source_version_hash": "e57e4dd463078b2ab0e0065c4916119eb4c7822d228c72bd95d7c0357ae5bde3", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S3-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S3-007', 'source'::public.t3a_content_family, 'THE COMPLAINT AND THE TWO ACCOUNTS', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE COMPLAINT AND THE TWO ACCOUNTS", "source_digest": "816d5256f01e9e8c53cd12b512c9e1a02aa15e86bf9bfa25b399e6adbf9b1f35", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You coordinate a program in which two team members from different functions must continue working together. One has raised a written complaint about the other''s conduct with the people function; the people function has confirmed receipt and told you the process is running and that you should not investigate. What the record shows: the two are jointly named on a deliverable due in three weeks; the people function''s process has no stated completion date; the deliverable requires them to exchange work twice in that period; the people function has said working arrangements are yours to set; and neither party has asked you to change anything."}], "submission_instructions": "Produce the position you would put about the working arrangement; what you would ask each party and the people function; what you would propose and what you would move on; and what would be agreed, recorded and taken forward. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options — all confined to the working arrangement"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options — all confined to the working arrangement"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options — all confined to the working arrangement"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options — all confined to the working arrangement"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options — all confined to the working arrangement"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "NOT SERVED", "basis": "A route the submission names is proposed, not used"}, {"question": "Q-D5-06b", "state": "NOT SERVED", "basis": "The source designates no available_routes item, so the bound question cannot be offered"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The deliverable date is the persistence point; the process has none"}, {"question": "Q-D5-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "SI1", "Item text": "the deliverable due in three weeks", "Where the participant meets it": "Pack document D1", "Quoted text": "jointly named on a deliverable due in three weeks"}, {"Item": "SI2", "Item text": "the two exchange points the work requires", "Where the participant meets it": "Pack document D1", "Quoted text": "exchange work twice in that period"}, {"Item": "SI3", "Item text": "the people function''s instruction that working arrangements are the participant''s to set", "Where the participant meets it": "Pack document D1", "Quoted text": "working arrangements are yours to set"}], "source_sheet": {"d5_situation_class": "SC-D5-7", "workplace_demand": "Preparing a working arrangement for two team members jointly named on one deliverable while a people process runs between them.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; whether an agreement and its recording were stated; what was stated about the difference continuing.", "irrelevant_conduct": "Everything about the complaint itself. It is the condition that makes the working arrangement a D5 situation and it is never the record.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": "SENSITIVE_CONTENT", "permitted_administration_variance": "Accommodations are recorded with the submission; the window may be extended as an accommodation and the extension is recorded.", "unsupported_inferences": "Any view of the complaint, its merits, either party''s conduct or credibility, or what occurred; that separating the parties is protective or avoidant; anything about sensitivity.", "compatibility_class": "S3-ASYNC-SUBMISSION", "designated_positions": [{"id": "DP1", "text": "the exchanges are routed through the participant so the two need not interact directly"}, {"id": "DP2", "text": "the deliverable is re-divided so no exchange is required"}, {"id": "DP3", "text": "the arrangement is unchanged and the people function''s process runs alongside"}], "designated_enquiries": [{"id": "DE1", "text": "what each party needs to complete their part of the deliverable"}, {"id": "DE2", "text": "what the people function permits in terms of working arrangements"}, {"id": "DE3", "text": "what the deliverable''s two exchange points require. **NO DESIGNATED ENQUIRY TOUCHES THE COMPLAINT"}], "shared_items": [{"id": "SI1", "text": "the deliverable due in three weeks"}, {"id": "SI2", "text": "the two exchange points the work requires"}, {"id": "SI3", "text": "the people function''s instruction that working arrangements are the participant''s to set"}], "available_options": [{"id": "AO1", "text": "exchanges routed through the participant"}, {"id": "AO2", "text": "the deliverable re-divided"}, {"id": "AO3", "text": "the date moved"}, {"id": "AO4", "text": "the people function asked to advise on the arrangement"}], "available_routes": [], "agreement_contents": [{"id": "AC1", "text": "the working arrangement"}, {"id": "AC2", "text": "who does what at each exchange point"}, {"id": "AC3", "text": "what is recorded and with whom"}], "counterpart_role": "The two team members and the people function.", "counterpart_position": "Neither party has asked for a change.", "difference_established": "Two people jointly named on a deliverable requiring exchange, with a process running between them.", "authority_relation": "The people function runs the complaint process and has directed no investigation; working arrangements are the participant''s.", "recording_route": "The program record and a note to the people function.", "persistence_point": "The deliverable in three weeks; the process has no completion date.", "list_note": "Not selectable in available_routes, because a route a submission names is proposed, not used: separate written notes to each party about the arrangement; a note to the people function; a written arrangement circulated to both.", "source_note": "Highest review standard: Demo-19 was retired from both D2 and D3 because its subject is a complaint about another person''s conduct. That is why it belongs in D5 — and it is the source most likely in the whole estate to produce a record about the complainant, the respondent or the allegation rather than about the participant. three people appear in this source and none of them is A subject of the record. No question observes any of them. No statement names any of them. No rendered sentence may describe the complaint''s substance, either party''s credibility, or any view of what occurred. It must not be approved without the fairness drafting test discharged by someone who has read this note, and it must not be the first D5 source served in any pilot. No route brings the two parties together, and A submission proposing one is recorded as an unlisted route under Q-D5-06 A2 — not as A judgment about the participant.", "situation_class_label": "A difference between two other parties affecting work held", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D5-S3-007", "stage_code": "S3", "source_version_hash": "816d5256f01e9e8c53cd12b512c9e1a02aa15e86bf9bfa25b399e6adbf9b1f35", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S3-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S4-001', 'source'::public.t3a_content_family, 'TWO TEAMS, ONE STRUCTURE', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "TWO TEAMS, ONE STRUCTURE", "source_digest": "21a886abf0584c9534ee581a096a03454bc907662f9888003a6d583f663926fb", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator makes no note of how anything was said and forms no view of any co-participant. The co-participants are role players; nothing they say is recorded, and nothing they say designates a position, an enquiry, a shared item, an option or a route.", "participant_pre_brief": "Two teams are being combined into one structure. You hold a workstream that spans both. What the record shows: the combined structure has one set of working practices to be settled in four weeks; each team has documented practices that differ on approval thresholds and on meeting cadence; the sponsor has said the combined team settles its own practices; both sets of practices are on the shared drive; and no lead has been named for the combined workstream.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have one item today. I will go round in the order on your cards, the three of you first, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where do you stand on the combined practices?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you putting forward, and what would you move on?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What would be agreed, and what if it is not settled in four weeks?", "direction": "Read once, verbatim.", "capture": [{"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said both sets of practices had been circulated. Had they?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "State your team''s approval threshold and that it has worked."}, {"Co-participant": "CP-2", "Position stated at the round": "State your team''s meeting cadence and that it has worked."}, {"Co-participant": "CP-3", "Position stated at the round": "As the sponsor''s representative, state that the practices are the team''s to settle in four weeks."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents and a recording route"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The four-week point is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "both practice documents on the shared drive", "Where the participant meets it": "The pre-brief", "Quoted text": "both sets of practices are on the shared drive"}, {"Item": "SI2", "Item text": "the four-week settlement point", "Where the participant meets it": "The pre-brief", "Quoted text": "to be settled in four weeks"}, {"Item": "SI3", "Item text": "the single combined structure both now work in", "Where the participant meets it": "The pre-brief", "Quoted text": "the combined structure has one set of working practices"}], "source_sheet": {"d5_situation_class": "SC-D5-6", "workplace_demand": "Settling working practices for one structure formed from two teams whose documented practices differ.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; which route was used; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The co-participants'' statements.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That either practice is better; any comparison of what P-obs said at B3 with B6 to infer whether A position held.", "compatibility_class": "S4-GROUP-ROUND", "designated_positions": [{"id": "DP1", "text": "the higher approval threshold and the lower cadence"}, {"id": "DP2", "text": "each practice kept for its own part of the workstream for one quarter"}, {"id": "DP3", "text": "a new single practice drafted from both"}], "designated_enquiries": [{"id": "DE1", "text": "what each threshold was set to address"}, {"id": "DE2", "text": "what each cadence supports"}, {"id": "DE3", "text": "what the sponsor expects at the four-week point"}], "shared_items": [{"id": "SI1", "text": "both practice documents on the shared drive"}, {"id": "SI2", "text": "the four-week settlement point"}, {"id": "SI3", "text": "the single combined structure both now work in"}], "available_options": [{"id": "AO1", "text": "one drafted practice"}, {"id": "AO2", "text": "parallel practices for a quarter"}, {"id": "AO3", "text": "the higher threshold with the higher cadence"}, {"id": "AO4", "text": "the sponsor asked to decide"}], "available_routes": [{"id": "AR1", "text": "this session"}], "agreement_contents": [{"id": "AC1", "text": "the threshold"}, {"id": "AC2", "text": "the cadence"}, {"id": "AC3", "text": "when it takes effect"}], "counterpart_role": "The two team representatives and the sponsor''s representative.", "counterpart_position": "Two differing documented practices.", "difference_established": "The two practice documents, established in the pre-brief and not by the co-participants.", "authority_relation": "The sponsor holds the structure; no member leads another.", "recording_route": "The circulated practice document.", "persistence_point": "The four-week point.", "exchange_test_point": "B6", "list_note": "Not selectable in available_routes, because only the session itself completes and is evidenced inside the session; a route the participant can only state is an intention: a written practice circulated for agreement; to the sponsor.", "source_note": null, "situation_class_label": "A working relationship to be formed where none exists", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D5-S4-001", "stage_code": "S4", "source_version_hash": "21a886abf0584c9534ee581a096a03454bc907662f9888003a6d583f663926fb", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S4-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S4-002', 'source'::public.t3a_content_family, 'THE PROJECT THAT HAS STOPPED MOVING', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE PROJECT THAT HAS STOPPED MOVING", "source_digest": "4a0d14cba2fba9021b542c68113c3c9acfecba3abd0f314a34485203c4196550", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator makes no note of how anything was said and forms no view of any co-participant. The co-participants are role players; nothing they say is recorded, and nothing they say designates a position, an enquiry, a shared item, an option or a route.", "participant_pre_brief": "A project has not moved for three weeks because two decisions are outstanding and each depends on the other being taken first. You hold delivery. What the record shows: decision A is a scope decision held by the business; decision B is a technical decision held by engineering; each has said in writing it can move once the other does; the project plan has three weeks of float left; and the steering group meets in five days.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have one item today. I will go round in the order on your cards, the three of you first, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where does the project stand?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you putting forward, and what would you move on?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What would be agreed before the steering group, and what if it is not?", "direction": "Read once, verbatim.", "capture": [{"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the float was exhausted. Is it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As business, state that you can decide once the technical position is known."}, {"Co-participant": "CP-2", "Position stated at the round": "As engineering, state that you can decide once the scope is fixed."}, {"Co-participant": "CP-3", "Position stated at the round": "As the project office, state the float remaining and the steering date."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "the three weeks of float", "Where the participant meets it": "The pre-brief", "Quoted text": "the project plan has three weeks of float left"}, {"Item": "SI2", "Item text": "the steering group in five days", "Where the participant meets it": "The pre-brief", "Quoted text": "the steering group meets in five days"}, {"Item": "SI3", "Item text": "both written positions, visible to all", "Where the participant meets it": "The pre-brief", "Quoted text": "each has said in writing it can move once the other does"}], "source_sheet": {"d5_situation_class": "SC-D5-1", "workplace_demand": "Moving a stalled project forward where two decisions each wait on the other, five days before the steering group.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; which route was used; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The two parties'' reasons, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That either party is stalling; that going to the steering group is escalation or prudence; anything about drive.", "compatibility_class": "S4-GROUP-ROUND", "designated_positions": [{"id": "DP1", "text": "a provisional scope is fixed so the technical decision can follow"}, {"id": "DP2", "text": "a provisional technical position is taken so the scope can follow"}, {"id": "DP3", "text": "both decisions are taken together in one session"}], "designated_enquiries": [{"id": "DE1", "text": "what each party needs from the other in terms"}, {"id": "DE2", "text": "what a provisional position would commit either to"}, {"id": "DE3", "text": "what the steering group expects in five days"}], "shared_items": [{"id": "SI1", "text": "the three weeks of float"}, {"id": "SI2", "text": "the steering group in five days"}, {"id": "SI3", "text": "both written positions, visible to all"}], "available_options": [{"id": "AO1", "text": "provisional scope first"}, {"id": "AO2", "text": "provisional technical first"}, {"id": "AO3", "text": "a joint session"}, {"id": "AO4", "text": "the steering group asked to break the deadlock"}], "available_routes": [{"id": "AR1", "text": "this session"}], "agreement_contents": [{"id": "AC1", "text": "which decision goes first"}, {"id": "AC2", "text": "what is provisional"}, {"id": "AC3", "text": "what goes to the steering group"}], "counterpart_role": "Business and engineering.", "counterpart_position": "Each can move once the other does.", "difference_established": "The two written positions and the mutual dependency, in the pre-brief.", "authority_relation": "Neither party reports to the participant.", "recording_route": "The project record.", "persistence_point": "The steering group in five days.", "exchange_test_point": "B6", "list_note": "Not selectable in available_routes, because only the session itself completes and is evidenced inside the session; a route the participant can only state is an intention: a joint written note to both parties; to the steering group.", "source_note": null, "situation_class_label": "Two parties holding different positions on a decision both must work under", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D5-S4-002", "stage_code": "S4", "source_version_hash": "4a0d14cba2fba9021b542c68113c3c9acfecba3abd0f314a34485203c4196550", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S4-002' and family = 'source'::public.t3a_content_family;
