  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE CONTRIBUTION BOTH SIDES CLAIM", "source_digest": "ce3288d26b69aa7566cf6dbb3b6c9d3177db4f158cd162a8f1cb517ce67a3f40", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator makes no note of how anything was said and forms no view of any co-participant. The co-participants are role players; nothing they say is recorded, and nothing they say designates a position, an enquiry, a shared item, an option or a route.", "participant_pre_brief": "A piece of work submitted to a client is claimed by two workstreams as their contribution. You hold the client relationship. What the record shows: the submission''s version history shows edits from both workstreams; the original outline is on the shared drive with one author named; the client has asked who to direct follow-up questions to; a joint credit line is available in the client record; and the reply is due to the client today.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have one item today. I will go round in the order on your cards, the three of you first, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "