, "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "State your workstream''s edits and their extent."}, {"Co-participant": "CP-2", "Position stated at the round": "State your workstream''s edits and their extent."}, {"Co-participant": "CP-3", "Position stated at the round": "As the project office, state that the version history and the original outline are both on the shared drive."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "Today''s client answer is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "the version history", "Where the participant meets it": "The pre-brief", "Quoted text": "the submission''s version history shows edits from both workstreams"}, {"Item": "SI2", "Item text": "the original outline on the shared drive", "Where the participant meets it": "The pre-brief", "Quoted text": "the original outline is on the shared drive"}, {"Item": "SI3", "Item text": "the client''s question due today", "Where the participant meets it": "The pre-brief", "Quoted text": "the reply is due to the client today"}], "source_sheet": {"d5_situation_class": "SC-D5-2", "workplace_demand": "Answering a client about a submission that two workstreams each claim, where the version history is on record.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; which route was used; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "Either workstream''s claim or conduct, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That either claim is stronger; that a joint line is a compromise; anything about fairness.", "compatibility_class": "S4-GROUP-ROUND", "designated_positions": [{"id": "DP1", "text": "the credit follows the original outline''s named author"}, {"id": "DP2", "text": "a joint credit line"}, {"id": "DP3", "text": "the credit follows the version history''s edit weight"}], "designated_enquiries": [{"id": "DE1", "text": "what each workstream''s edits changed"}, {"id": "DE2", "text": "what the original outline contains"}, {"id": "DE3", "text": "what the client needs the credit for"}], "shared_items": [{"id": "SI1", "text": "the version history"}, {"id": "SI2", "text": "the original outline on the shared drive"}, {"id": "SI3", "text": "the client''s question due today"}], "available_options": [{"id": "AO1", "text": "joint credit line"}, {"id": "AO2", "text": "credit to the outline author with both workstreams noted"}, {"id": "AO3", "text": "the client told both and given one contact"}, {"id": "AO4", "text": "the project office decides"}], "available_routes": [{"id": "AR1", "text": "this session"}], "agreement_contents": [{"id": "AC1", "text": "the credit line"}, {"id": "AC2", "text": "the client contact"}, {"id": "AC3", "text": "what the record shows"}], "counterpart_role": "The two workstream representatives.", "counterpart_position": "Each claims the contribution.", "difference_established": "Two claims against one version history, in the pre-brief.", "authority_relation": "The participant holds the client relationship; the project office holds the record.", "recording_route": "The client record.", "persistence_point": "The client''s question today.", "exchange_test_point": "B6", "list_note": "Not selectable in available_routes, because only the session itself completes and is evidenced inside the session; a route the participant can only state is an intention: a written note to the client; to the project office.", "source_note": null, "situation_class_label": "A contribution presented as another party''s", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D5-S4-003", "stage_code": "S4", "source_version_hash": "ce3288d26b69aa7566cf6dbb3b6c9d3177db4f158cd162a8f1cb517ce67a3f40", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S4-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S4-004', 'source'::public.t3a_content_family, 'THE POSITIONS NOT STATED IN THE ROOM', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE POSITIONS NOT STATED IN THE ROOM", "source_digest": "8be864703ebe671540ab5dfc0f9b6a9f1580ba09f788fb080fafcebf2cd5f065", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator makes no note of how anything was said and forms no view of any co-participant. The co-participants are role players; nothing they say is recorded, and nothing they say designates a position, an enquiry, a shared item, an option or a route.", "participant_pre_brief": "A decision is being taken in a group where two members have written positions on file that neither has stated aloud. You hold the decision''s delivery. What the record shows: both written positions are in the pre-read circulated to everyone; they differ from what has been said in the room so far; the decision is due at the end of this session; the pre-read is on the shared drive; and the chair has asked for a decision rather than a discussion.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have one item today. I will go round in the order on your cards, the three of you first, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where do you stand?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you putting forward, and what would you move on?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What would be agreed by the end of this session, and what if it is not?", "direction": "Read once, verbatim.", "capture": [{"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said everyone had read the pre-read. Had they?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "State a position that differs from your own written one."}, {"Co-participant": "CP-2", "Position stated at the round": "State that you have no strong view."}, {"Co-participant": "CP-3", "Position stated at the round": "As the chair, state that a decision is needed by the end of the session."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The end of the session is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "the circulated pre-read", "Where the participant meets it": "The pre-brief", "Quoted text": "both written positions are in the pre-read circulated to everyone"}, {"Item": "SI2", "Item text": "the end-of-session decision point", "Where the participant meets it": "The pre-brief", "Quoted text": "the decision is due at the end of this session"}, {"Item": "SI3", "Item text": "the shared drive holding both written positions", "Where the participant meets it": "The pre-brief", "Quoted text": "the pre-read is on the shared drive"}], "source_sheet": {"d5_situation_class": "SC-D5-1", "workplace_demand": "Taking a decision in a group where two members'' written positions differ from what has been said in the room.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; which route was used; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "Why any member said what they said, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That any member was being evasive; that naming the pre-read is confrontational; anything about courage.", "compatibility_class": "S4-GROUP-ROUND", "designated_positions": [{"id": "DP1", "text": "the decision as the pre-read sets it out"}, {"id": "DP2", "text": "the decision deferred until the written positions are on the table"}, {"id": "DP3", "text": "a decision with a stated review point"}], "designated_enquiries": [{"id": "DE1", "text": "what each written position sets out"}, {"id": "DE2", "text": "what has changed since the pre-read"}, {"id": "DE3", "text": "what the chair needs by the end of the session"}], "shared_items": [{"id": "SI1", "text": "the circulated pre-read"}, {"id": "SI2", "text": "the end-of-session decision point"}, {"id": "SI3", "text": "the shared drive holding both written positions"}], "available_options": [{"id": "AO1", "text": "decide as the pre-read sets out"}, {"id": "AO2", "text": "defer with a named date"}, {"id": "AO3", "text": "decide with a four-week review"}, {"id": "AO4", "text": "the chair takes the decision"}], "available_routes": [{"id": "AR1", "text": "this session"}], "agreement_contents": [{"id": "AC1", "text": "the decision"}, {"id": "AC2", "text": "any review point"}, {"id": "AC3", "text": "what the record shows"}], "counterpart_role": "The two members and the chair.", "counterpart_position": "Two written positions differing from what has been said aloud.", "difference_established": "The pre-read positions against the room, in the pre-brief.", "authority_relation": "The chair holds the session.", "recording_route": "The session note.", "persistence_point": "The end of the session.", "exchange_test_point": "B6", "list_note": "Not selectable in available_routes, because only the session itself completes and is evidenced inside the session; a route the participant can only state is an intention: a written note circulated after it; to the chair separately.", "source_note": "counterpart_position: Why A member''s spoken position differs from their written one is not established and no question may recover IT.", "situation_class_label": "Two parties holding different positions on a decision both must work under", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D5-S4-004", "stage_code": "S4", "source_version_hash": "8be864703ebe671540ab5dfc0f9b6a9f1580ba09f788fb080fafcebf2cd5f065", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S4-004' and family = 'source'::public.t3a_content_family;
