  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "TWO WORKING CONVENTIONS ON ONE DELIVERABLE", "source_digest": "fe762e4ca0fbd834ad4fe20313bb1a1a548198d4dcc25065f7032805e638206f", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator makes no note of how anything was said and forms no view of any co-participant. The co-participants are role players; nothing they say is recorded, and nothing they say designates a position, an enquiry, a shared item, an option or a route.", "participant_pre_brief": "Two groups working on one deliverable follow different documented conventions. What the record shows: one convention requires written sign-off at each stage; the other requires decisions taken in the meeting and minuted after; both conventions are written and held on file; the deliverable has four stages and is due in six weeks; and the two conventions cannot both govern the same stage.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have one item today. I will go round in the order on your cards, the three of you first, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, 