  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S4-006', 'source'::public.t3a_content_family, 'THE PARTY WITH NO REASON TO HELP', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE PARTY WITH NO REASON TO HELP", "source_digest": "fa8a29f2e942e850153c8dcbf344d04a86f4afa8a88ab1fa9301ee6c179f470c", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator makes no note of how anything was said and forms no view of any co-participant. The co-participants are role players; nothing they say is recorded, and nothing they say designates a position, an enquiry, a shared item, an option or a route.", "participant_pre_brief": "You need a contribution from a team that gains nothing from your program and reports elsewhere. What the record shows: the contribution is about five days of that team''s effort; your program''s business case does not name that team; their own objectives for the quarter are published and do not include it; a reciprocal contribution from your team is possible and has not been offered; and your sponsor has said they will not instruct another function.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have one item today. I will go round in the order on your cards, the three of you first, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What are you asking for?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you putting forward, and what would you move on?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What would be agreed, and what if it is not?", "direction": "Read once, verbatim.", "capture": [{"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the sponsor had cleared this with their director. Had they?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the other team''s lead, state your published quarterly objectives."}, {"Co-participant": "CP-2", "Position stated at the round": "As your program office, state the five-day estimate."}, {"Co-participant": "CP-3", "Position stated at the round": "As the sponsor''s representative, state that no instruction will be given to another function."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The quarter end is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "the published quarterly objectives", "Where the participant meets it": "The pre-brief", "Quoted text": "their own objectives for the quarter are published"}, {"Item": "SI2", "Item text": "the five-day estimate", "Where the participant meets it": "The pre-brief", "Quoted text": "about five days of that team''s effort"}, {"Item": "SI3", "Item text": "the sponsor''s position that no instruction will be given", "Where the participant meets it": "The pre-brief", "Quoted text": "your sponsor has said they will not instruct another function"}], "source_sheet": {"d5_situation_class": "SC-D5-5", "workplace_demand": "Obtaining about five days of effort from a team whose published objectives do not include the contribution.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; which route was used; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The other team''s priorities, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the other team should help; that offering a reciprocal is transactional; anything about influence.", "compatibility_class": "S4-GROUP-ROUND", "designated_positions": [{"id": "DP1", "text": "the five days requested as a contribution"}, {"id": "DP2", "text": "the five days in exchange for a named reciprocal contribution"}, {"id": "DP3", "text": "the work re-scoped so less is needed"}], "designated_enquiries": [{"id": "DE1", "text": "what the published objectives commit that team to"}, {"id": "DE2", "text": "what a reciprocal contribution would be worth to them"}, {"id": "DE3", "text": "what part of the five days is unavoidable"}], "shared_items": [{"id": "SI1", "text": "the published quarterly objectives"}, {"id": "SI2", "text": "the five-day estimate"}, {"id": "SI3", "text": "the sponsor''s position that no instruction will be given"}], "available_options": [{"id": "AO1", "text": "a named reciprocal contribution"}, {"id": "AO2", "text": "the work re-scoped to two days"}, {"id": "AO3", "text": "the contribution deferred to next quarter''s objectives"}, {"id": "AO4", "text": "both directors asked jointly"}], "available_routes": [{"id": "AR1", "text": "this session"}], "agreement_contents": [{"id": "AC1", "text": "what is contributed"}, {"id": "AC2", "text": "what is given in return"}, {"id": "AC3", "text": "when"}], "counterpart_role": "The other team''s lead.", "counterpart_position": "Published objectives that do not include the contribution.", "difference_established": "A needed contribution outside the other team''s published objectives.", "authority_relation": "\"your sponsor has said they will not instruct another function.\" Exact pre-brief text.", "recording_route": "A note to both directors.", "persistence_point": "The quarter ends and the objectives stand.", "exchange_test_point": "B6", "list_note": "Not selectable in available_routes, because only the session itself completes and is evidenced inside the session; a route the participant can only state is an intention: a joint note to both directors; through the sponsor.", "source_note": null, "situation_class_label": "Something needed from a party over whom there is no authority", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D5-S4-006", "stage_code": "S4", "source_version_hash": "fa8a29f2e942e850153c8dcbf344d04a86f4afa8a88ab1fa9301ee6c179f470c", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S4-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S4-007', 'source'::public.t3a_content_family, 'WORKING TOGETHER AFTER A MISSED COMMITMENT', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "WORKING TOGETHER AFTER A MISSED COMMITMENT", "source_digest": "b9741d681755287a66c25a93018fca19c5b8ab751ca0510095c4531b1a4f38c6", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator makes no note of how anything was said and forms no view of any co-participant. The co-participants are role players; nothing they say is recorded, and nothing they say designates a position, an enquiry, a shared item, an option or a route.", "participant_pre_brief": "A commitment from another party was not met and the two of you must continue working together on the same deliverable. What the record shows: the commitment and its date are in the joint plan; the date passed eleven days ago; the deliverable requires three further exchanges between you; no reason for the miss has been recorded; the joint plan can be amended by both parties together; and the next exchange is due in four days.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have one item today. I will go round in the order on your cards, the three of you first, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where does the joint plan stand?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you putting forward, and what would you move on?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What would be agreed, and what if the next exchange is not met?", "direction": "Read once, verbatim.", "capture": [{"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the missed date had been re-baselined. Had it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the other party, state that the next exchange will be met."}, {"Co-participant": "CP-2", "Position stated at the round": "As the project office, state the joint plan''s dates."}, {"Co-participant": "CP-3", "Position stated at the round": "As a third workstream, state what you need from the deliverable and when."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The next exchange is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "the joint plan and its dates", "Where the participant meets it": "The pre-brief", "Quoted text": "the commitment and its date are in the joint plan"}, {"Item": "SI2", "Item text": "the three remaining exchanges", "Where the participant meets it": "The pre-brief", "Quoted text": "the deliverable requires three further exchanges between you"}, {"Item": "SI3", "Item text": "the next exchange due in four days", "Where the participant meets it": "The pre-brief", "Quoted text": "the next exchange is due in four days"}], "source_sheet": {"d5_situation_class": "SC-D5-4", "workplace_demand": "Continuing joint work after a missed commitment, with three exchanges still required.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; which route was used; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The other party''s reason or conduct, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the other party failed, which is A D2 matter; that a checkpoint is distrust; anything about tolerance.", "compatibility_class": "S4-GROUP-ROUND", "designated_positions": [{"id": "DP1", "text": "the joint plan stands and the next exchange holds"}, {"id": "DP2", "text": "the plan is re-baselined with the three exchanges re-dated"}, {"id": "DP3", "text": "the exchanges are reduced from three to two"}], "designated_enquiries": [{"id": "DE1", "text": "what is needed for the next exchange to be met"}, {"id": "DE2", "text": "what the three exchanges each require"}, {"id": "DE3", "text": "what the third workstream needs and when"}], "shared_items": [{"id": "SI1", "text": "the joint plan and its dates"}, {"id": "SI2", "text": "the three remaining exchanges"}, {"id": "SI3", "text": "the next exchange due in four days"}], "available_options": [{"id": "AO1", "text": "re-baseline the plan"}, {"id": "AO2", "text": "reduce to two exchanges"}, {"id": "AO3", "text": "a checkpoint two days before each exchange"}, {"id": "AO4", "text": "the project office holds the dates"}], "available_routes": [{"id": "AR1", "text": "this session"}], "agreement_contents": [{"id": "AC1", "text": "the exchange dates"}, {"id": "AC2", "text": "any checkpoint"}, {"id": "AC3", "text": "what is filed in the plan"}], "counterpart_role": "The other party.", "counterpart_position": "The next exchange will be met.", "difference_established": "A missed commitment with three exchanges still required.", "authority_relation": "Peers; the project office holds the plan.", "recording_route": "The joint plan.", "persistence_point": "The next exchange in four days.", "exchange_test_point": "B6", "list_note": "Not selectable in available_routes, because only the session itself completes and is evidenced inside the session; a route the participant can only state is an intention: an amended joint plan circulated; to both managers.", "source_note": "counterpart_position: No reason for the miss is established and no question may recover one.", "situation_class_label": "Divided work not arriving from one side", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D5-S4-007", "stage_code": "S4", "source_version_hash": "b9741d681755287a66c25a93018fca19c5b8ab751ca0510095c4531b1a4f38c6", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S4-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S4-008', 'source'::public.t3a_content_family, 'THE WORK HANDED OVER AND HANDED BACK', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE WORK HANDED OVER AND HANDED BACK", "source_digest": "99984bb29738e5dc6d449e285c65025d30a6fb28efd8a3dd97fd3cecf0769de3", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator makes no note of how anything was said and forms no view of any co-participant. The co-participants are role players; nothing they say is recorded, and nothing they say designates a position, an enquiry, a shared item, an option or a route.", "participant_pre_brief": "Work you delegated has come back incomplete twice and the second return has put a client date at risk. You and the other party must settle how the remaining work is done. What the record shows: the delegation note lists five components; three came back complete and two did not, on both occasions; the client date is in nine days; the two incomplete components need about four days between them; and the delegation note can be revised by either party with the other''s agreement.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have one item today. I will go round in the order on your cards, the three of you first, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where does the delegation stand?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you putting forward, and what would you move on?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What would be agreed, and what if the two components are not done?", "direction": "Read once, verbatim.", "capture": [{"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said all five had been agreed in the note. Were they?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "As the other party, state which three components were completed."}, {"Co-participant": "CP-2", "Position stated at the round": "As the client account lead, state the client date."}, {"Co-participant": "CP-3", "Position stated at the round": "As the resource manager, state what capacity is available in the nine days."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Ao-01 is A change to the participant''s own load"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Ao-01 is A change to the participant''s own load"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Ao-01 is A change to the participant''s own load"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Ao-01 is A change to the participant''s own load"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Ao-01 is A change to the participant''s own load"}, {"question": "Q-D5-06", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents and a revisable note"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The client date is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "the delegation note listing five components", "Where the participant meets it": "The pre-brief", "Quoted text": "the delegation note lists five components"}, {"Item": "SI2", "Item text": "the client date in nine days", "Where the participant meets it": "The pre-brief", "Quoted text": "the client date is in nine days"}, {"Item": "SI3", "Item text": "the four days of work the two components need", "Where the participant meets it": "The pre-brief", "Quoted text": "need about four days between them"}], "source_sheet": {"d5_situation_class": "SC-D5-4", "workplace_demand": "Settling with the other party how delegated work that came back incomplete twice is completed, nine days before a client date.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; which route was used; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The other party''s reasons, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That the other party failed, which is A D2 matter; that taking the work back is decisive or a retreat; anything about delegation skill.", "compatibility_class": "S4-GROUP-ROUND", "designated_positions": [{"id": "DP1", "text": "the delegation note stands and the two components are completed"}, {"id": "DP2", "text": "the two components return to the participant"}, {"id": "DP3", "text": "the note is revised so the two components are split"}], "designated_enquiries": [{"id": "DE1", "text": "what the two components require to complete"}, {"id": "DE2", "text": "what capacity exists in the nine days"}, {"id": "DE3", "text": "what the client date depends on"}], "shared_items": [{"id": "SI1", "text": "the delegation note listing five components"}, {"id": "SI2", "text": "the client date in nine days"}, {"id": "SI3", "text": "the four days of work the two components need"}], "available_options": [{"id": "AO1", "text": "the participant takes the two components"}, {"id": "AO2", "text": "the note revised and the components split"}, {"id": "AO3", "text": "additional capacity requested"}, {"id": "AO4", "text": "the client date moved"}], "available_routes": [{"id": "AR1", "text": "this session"}], "agreement_contents": [{"id": "AC1", "text": "who does the two components"}, {"id": "AC2", "text": "by when"}, {"id": "AC3", "text": "what the revised note says"}], "counterpart_role": "The other party.", "counterpart_position": "Three components were completed.", "difference_established": "Two components incomplete on two occasions against a five-component note.", "authority_relation": "The participant delegated; the account lead holds the client.", "recording_route": "The delegation note.", "persistence_point": "The client date in nine days.", "exchange_test_point": "B6", "list_note": "Not selectable in available_routes, because only the session itself completes and is evidenced inside the session; a route the participant can only state is an intention: a revised delegation note circulated; to the account lead about the date.", "source_note": null, "situation_class_label": "Divided work not arriving from one side", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D5-S4-008", "stage_code": "S4", "source_version_hash": "99984bb29738e5dc6d449e285c65025d30a6fb28efd8a3dd97fd3cecf0769de3", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S4-008' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S4-009', 'source'::public.t3a_content_family, 'TWO DIRECTIONS FOR THE SAME PROGRAM', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "TWO DIRECTIONS FOR THE SAME PROGRAM", "source_digest": "2498ca951272dec00ab02accea350adf80a3a66f172c3ff3af34c0c286a0e6e2", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator makes no note of how anything was said and forms no view of any co-participant. The co-participants are role players; nothing they say is recorded, and nothing they say designates a position, an enquiry, a shared item, an option or a route.", "participant_pre_brief": "Two written directions for the same program have been issued by different parts of the organization and cannot both be followed. You hold delivery. What the record shows: both directions are in writing and neither has been withdrawn; one requires the program to standardize across regions, the other to tailor by region; the program board meets in two weeks; a hybrid has been used on one previous program and is documented; and neither issuing party reports to the other.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have one item today. I will go round in the order on your cards, the three of you first, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where does the program stand?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you putting forward, and what would you move on?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What would be agreed before the board, and what if it is not?", "direction": "Read once, verbatim.", "capture": [{"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said one direction had been withdrawn. Has it?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "State the standardisation direction."}, {"Co-participant": "CP-2", "Position stated at the round": "State the tailoring direction."}, {"Co-participant": "CP-3", "Position stated at the round": "As the program office, state the board date and the documented hybrid precedent."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "Three agreement contents"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The board is the authority"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "both written directions", "Where the participant meets it": "The pre-brief", "Quoted text": "both directions are in writing and neither has been withdrawn"}, {"Item": "SI2", "Item text": "the board date", "Where the participant meets it": "The pre-brief", "Quoted text": "the program board meets in two weeks"}, {"Item": "SI3", "Item text": "the documented hybrid precedent", "Where the participant meets it": "The pre-brief", "Quoted text": "a hybrid has been used on one previous program and is documented"}], "source_sheet": {"d5_situation_class": "SC-D5-1", "workplace_demand": "Holding a program that has received two written directions that cannot both be followed, two weeks before the board.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; which route was used; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The two parties'' disagreement, which is the condition of the situation and never the record.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That either direction is right; that going to the board is escalation; anything about political judgment.", "compatibility_class": "S4-GROUP-ROUND", "designated_positions": [{"id": "DP1", "text": "standardisation as the first direction requires"}, {"id": "DP2", "text": "tailoring as the second requires"}, {"id": "DP3", "text": "the documented hybrid"}], "designated_enquiries": [{"id": "DE1", "text": "what each direction requires in terms"}, {"id": "DE2", "text": "what the documented hybrid involved"}, {"id": "DE3", "text": "what the board expects in two weeks"}], "shared_items": [{"id": "SI1", "text": "both written directions"}, {"id": "SI2", "text": "the board date"}, {"id": "SI3", "text": "the documented hybrid precedent"}], "available_options": [{"id": "AO1", "text": "the hybrid"}, {"id": "AO2", "text": "standardisation with regional exceptions"}, {"id": "AO3", "text": "tailoring within a standard frame"}, {"id": "AO4", "text": "both directions put to the board"}], "available_routes": [{"id": "AR1", "text": "this session"}], "agreement_contents": [{"id": "AC1", "text": "which approach the program follows"}, {"id": "AC2", "text": "what goes to the board"}, {"id": "AC3", "text": "who informs whom"}], "counterpart_role": "The two issuing parties.", "counterpart_position": "Two irreconcilable written directions.", "difference_established": "The two written directions, in the pre-brief.", "authority_relation": "Neither issuing party reports to the other or to the participant.", "recording_route": "The program record.", "persistence_point": "The board in two weeks.", "exchange_test_point": "B6", "list_note": "Not selectable in available_routes, because only the session itself completes and is evidenced inside the session; a route the participant can only state is an intention: a joint note to both issuing parties; to the board secretary.", "source_note": null, "situation_class_label": "Two parties holding different positions on a decision both must work under", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D5-S4-009", "stage_code": "S4", "source_version_hash": "2498ca951272dec00ab02accea350adf80a3a66f172c3ff3af34c0c286a0e6e2", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S4-009' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D5-S4-010', 'source'::public.t3a_content_family, 'THE TEAM PUT BACK TOGETHER', 'D5', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.0', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 4, "title": "THE TEAM PUT BACK TOGETHER", "source_digest": "21ce72582695a6c65a9489132424f52cafd0c2e26298e1bddde9bbcfaed9e533", "mentor_brief": "The facilitator facilitates the session and observes the observed participant only. At B1 the facilitator states the speaking order aloud: the three co-participants, then the observed participant. During the B2 round the facilitator does not look at, gesture towards or address the observed participant. The facilitator reads the scripted text verbatim, reacts to nothing, and does not press, repeat or escalate, whatever the observed participant says or does not say. The facilitator makes no note of how anything was said and forms no view of any co-participant. The co-participants are role players; nothing they say is recorded, and nothing they say designates a position, an enquiry, a shared item, an option or a route.", "participant_pre_brief": "A team is being reconstituted after a period in which it was split across two programs. You hold a workstream in the reconstituted team. What the record shows: five members return from two different programs; each program used different reporting practices, both documented; the reconstituted team has one deliverable due in eight weeks; no working arrangement has been set; and the team lead has asked the members to propose one within a week.", "script": [{"beat": "B1", "type": "SAY", "spoken": "We have one item today. I will go round in the order on your cards, the three of you first, then you. Two minutes each.", "direction": null, "capture": []}, {"beat": "B2", "type": "ROUND", "spoken": "Over to you, in the order I gave.", "direction": "Invite the three co-participants in the stated order. Do not address the observed participant.", "capture": [{"set": "C1", "state": "open"}, {"set": "C1b", "state": "open"}, {"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C3", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5", "state": "open"}, {"set": "C5b", "state": "open"}, {"set": "C6", "state": "open"}, {"set": "C6b", "state": "open"}, {"set": "C7", "state": "open"}, {"set": "C7b", "state": "open"}, {"set": "C8", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where do you stand on the working arrangement?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C1b", "state": "update"}, {"set": "C2", "state": "update"}, {"set": "C2b", "state": "update"}, {"set": "C3", "state": "update"}, {"set": "C3b", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "What are you putting forward, and what would you move on?", "direction": "Read once, verbatim.", "capture": [{"set": "C4", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5", "state": "update"}, {"set": "C5b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What would be agreed in the week, and what if it is not?", "direction": "Read once, verbatim.", "capture": [{"set": "C6", "state": "update"}, {"set": "C6b", "state": "update"}, {"set": "C7", "state": "update"}, {"set": "C7b", "state": "update"}, {"set": "C8", "state": "update"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so the position is right — you said the lead had already set the arrangement. Had they?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is the session. Thank you all.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3", "state": "final"}, {"set": "C4", "state": "final"}, {"set": "C5", "state": "final"}, {"set": "C6", "state": "final"}, {"set": "C7", "state": "final"}, {"set": "C8", "state": "final"}, {"set": "C9", "state": "final"}]}], "co_participant_positions": [{"Co-participant": "CP-1", "Position stated at the round": "State the reporting practice from one program."}, {"Co-participant": "CP-2", "Position stated at the round": "State the reporting practice from the other."}, {"Co-participant": "CP-3", "Position stated at the round": "As the team lead, state the one-week point and the eight-week deliverable."}], "impact_assessment": [{"Part": "1. Shared material", "Finding": "Only the scripted situation is placed before the group, and it names no real organization", "Controls": "IA-01 shown in one shared window holding only the shared material"}, {"Part": "2. Identity", "Finding": "The observed participant is the authenticated participant; the three co-participants are role players", "Controls": "IA-02 platform account authentication; role players are never observed"}, {"Part": "3. Recording", "Finding": "Nothing is recorded", "Controls": "IA-03 no media persists"}, {"Part": "4. Correction", "Finding": "A correction reaches only the observed participant''s record", "Controls": "IA-04 a correction reaches only the observed participant''s record"}, {"Part": "5. Withdrawal", "Finding": "Withdrawal removes the participant''s determinations from composition only", "Controls": "IA-05 withdrawal excludes from composition; history retained"}, {"Part": "6. Group composition", "Finding": "One observed participant, three role players and one facilitator", "Controls": "IA-06 composition record and confidentiality undertaking from each role player"}, {"Part": "7. Accommodation", "Finding": "An accommodation is settled before composition and never changes the observation during the session", "Controls": "IA-07 settled before composition"}], "impact_result": "Completed", "question_applicability": [{"question": "Q-D5-01", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-01b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-02", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-03", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-04", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-05", "state": "DIRECT", "basis": "Three positions, three enquiries, three shared items, four options"}, {"question": "Q-D5-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-06", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-07", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D5-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D5-08", "state": "DIRECT", "basis": "The one-week point is the persistence point"}, {"question": "Q-D5-09", "state": "DIRECT", "basis": "In play on this source"}], "material_map": [{"Item": "SI1", "Item text": "both documented practices", "Where the participant meets it": "The pre-brief", "Quoted text": "each program used different reporting practices, both documented"}, {"Item": "SI2", "Item text": "the one-week proposal point", "Where the participant meets it": "The pre-brief", "Quoted text": "propose one within a week"}, {"Item": "SI3", "Item text": "the eight-week deliverable, common to all", "Where the participant meets it": "The pre-brief", "Quoted text": "one deliverable due in eight weeks"}], "source_sheet": {"d5_situation_class": "SC-D5-6", "workplace_demand": "Forming one working arrangement for a reconstituted team whose returning members used different documented reporting practices.", "relevant_conduct": "The position stated as the participant''s own; whether the other position was asked about; which shared items were named; what was proposed; what change to the participant''s own position was stated; which route was used; whether an agreement and its recording were stated; what was stated about the difference continuing; what was stated when the participant''s own part was put back.", "irrelevant_conduct": "The members'' program histories, never recorded.", "stated_standard": null, "stated_standard_source_quote_or_location": null, "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named, and no counterpart is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations affecting turn order or response window are recorded and set timing_not_comparable.", "unsupported_inferences": "That either practice is better; that proposing early is leadership; anything about team building.", "compatibility_class": "S4-GROUP-ROUND", "designated_positions": [{"id": "DP1", "text": "one of the two documented practices adopted whole"}, {"id": "DP2", "text": "a new practice drafted from both"}, {"id": "DP3", "text": "each workstream keeps its own practice for the first deliverable"}], "designated_enquiries": [{"id": "DE1", "text": "what each practice requires and at what cadence"}, {"id": "DE2", "text": "what the eight-week deliverable needs from reporting"}, {"id": "DE3", "text": "what the lead expects at the one-week point"}], "shared_items": [{"id": "SI1", "text": "both documented practices"}, {"id": "SI2", "text": "the one-week proposal point"}, {"id": "SI3", "text": "the eight-week deliverable, common to all"}], "available_options": [{"id": "AO1", "text": "one practice adopted whole"}, {"id": "AO2", "text": "a drafted practice"}, {"id": "AO3", "text": "parallel practices for this deliverable"}, {"id": "AO4", "text": "the lead decides"}], "available_routes": [{"id": "AR1", "text": "this session"}], "agreement_contents": [{"id": "AC1", "text": "the practice"}, {"id": "AC2", "text": "the cadence"}, {"id": "AC3", "text": "what goes to the lead"}], "counterpart_role": "The returning members and the team lead.", "counterpart_position": "Two documented practices.", "difference_established": "Two documented practices and no working arrangement.", "authority_relation": "The lead has asked the members to propose.", "recording_route": "The circulated proposal.", "persistence_point": "The one-week point.", "exchange_test_point": "B6", "list_note": "Not selectable in available_routes, because only the session itself completes and is evidenced inside the session; a route the participant can only state is an intention: a written proposal circulated to the team; to the team lead.", "source_note": null, "situation_class_label": "A working relationship to be formed where none exists", "observation_mode_label": "group_session", "min_seconds": 900, "max_seconds": 1500}, "source_identifier": "SRC-D5-S4-010", "stage_code": "S4", "source_version_hash": "21ce72582695a6c65a9489132424f52cafd0c2e26298e1bddde9bbcfaed9e533", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D5-S4-010' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_d1_content_load_event(env_state, content_object_id, content_version_id, governed_status, notes) select 'design_only', o.content_object_id, v.content_version_id, 'DISABLED_PENDING_DECISION', 'T3A-D5-EXEC-001 v2.0 loaded not servable' from public.t3a_content_object o join public.t3a_d1_content_version v on v.content_object_id = o.content_object_id where o.dimension_id = 'D5' and o.identifier like 'T3A-D5-EXEC-001%' or (o.dimension_id = 'D5' and o.identifier like 'SRC-D5-%');
